func startRuntimeObservability(ctx context.Context, cfg Config, role, member string) (*runtimeObservability, error) {
	settings := cfg.Observability
	if err := settings.Validate(); err != nil {
		return nil, err
	}
	runtime := &runtimeObservability{config: settings, cell: cfg.NATS.Cell, member: member, role: role,
		operationObservations: &operationObservationAPI{cell: cfg.NATS.Cell},
		registry:              observability.NewRegistry(true), health: new(observability.Health),
		events: observability.NewEventBus(observability.DefaultEventCapacity)}
	logger, err := observability.NewLogger(os.Stderr,
		observability.LogConfig{Format: settings.LogFormat, Level: settings.LogLevel}, runtime.events,
		observability.Identity(role, cfg.NATS.Cell)...)
	if err != nil {
		return nil, err
	}
	observability.ConfigureDefault(logger)
	runtime.registry.Register(observability.LogMetrics)
	runtime.health.Add(observability.Check{Name: "startup", Run: func(context.Context) (bool, string) {
		if runtime.started.Load() {
			return true, "runtime started"
		}
		return false, "runtime is still starting"
	}})
	if role == "controller" {
		runtime.usage = capacity.NewStore(cfg.NATS.Cell)
		runtime.startDecisionJournal(ctx)
	}
	server, err := observability.NewServer(settings, observability.ServerDeps{Registry: runtime.registry,
		Health: runtime.health, Events: runtime.events, LocalSessions: role == "host"})
	if err != nil {
		// An unusable bearer token file (missing, shared or malformed) fails
		// closed for the listener only: nothing is served, and the role
		// keeps running exactly as when the port cannot be bound.
		slog.WarnContext(ctx, "observability listener unusable; continuing without it",
			observability.ComponentKey, "observability", "error", err)
		return runtime, nil
	}
	runtime.mountUsage(server)
	runtime.operationObservations.mount(server)
	// A token-protected listener issues browser sessions; a tokenless
	// one is loopback only and refuses DNS names against rebinding.
	board := dashboard.New(dashboard.Options{Health: runtime.health, Events: runtime.events,
		SignOut: settings.BearerTokenFile != "", RequireLiteralHost: settings.BearerTokenFile == ""})
	board.Mount(server)
	serveErrors, err := server.Start(ctx, settings)
	if err != nil {
		slog.WarnContext(ctx, "observability listener unavailable; continuing without it",
			observability.ComponentKey, "observability", "address", settings.Address(), "error", err)
		return runtime, nil
	}
	go watchObservabilityListener(serveErrors)
	runtime.server = server
	runtime.addBoard(board, server)
	slog.InfoContext(ctx, "observability listener ready", observability.ComponentKey, "observability",
		"address", server.Addr().String())
	return runtime, nil
}

func watchObservabilityListener(serveErrors <-chan error) {
	if serveErrors == nil {
		return
	}
	if err, ok := <-serveErrors; ok && err != nil {
		slog.Warn("observability listener stopped serving",
			observability.ComponentKey, "observability", "error", err)
	}
}

func (runtime *runtimeObservability) attachController(ctx context.Context, observed controllerObservation,
	filesystems []observability.FilesystemRole,
) error {
	runtime.sessionJS, runtime.sessionReplicas = observed.nats.JetStream(), observed.replicas
	runtime.attachLogs(ctx, observed)
	if runtime.server != nil && runtime.config.BearerTokenFile != "" {
		go retryAttachment(ctx, "dashboard", "dashboard session storage", func(attempt context.Context) error {
			store, err := observability.OpenSessionStore(attempt, runtime.sessionJS, runtime.sessionReplicas, "local."+runtime.member)
			if err != nil {
				return err
			}
			return runtime.server.SetSessionStore(attempt, store)
		})
	}
	runtime.registry.Register(delivery.Metrics)
	runtime.registry.Register(oci.Metrics)
	runtime.registry.Register(placement.Metrics)
	runtime.health.Add(observability.Check{Name: "nats", Run: func(context.Context) (bool, string) {
		if observed.nats.Ready() {
			return true, "regional broker connected"
		}
		return false, "regional broker is not connected"
	}})
	runtime.health.Add(observability.Check{Name: "cluster", Run: func(context.Context) (bool, string) {
		if observed.nats.FullClusterReady(observed.replicas) {
			return true, fmt.Sprintf("%d of %d replicas routed", observed.replicas, observed.replicas)
		}
		return false, "regional cluster is below its full replica count"
	}})
	runtime.health.Add(observability.Check{Name: "authority", Run: func(context.Context) (bool, string) {
		if lease := observed.authority.Current(); lease.Ready {
			if lease.Leader {
				return true, fmt.Sprintf("this controller holds the lease, epoch %d", lease.Epoch)
			}
			return true, fmt.Sprintf("lease observed, epoch %d", lease.Epoch)
		}
		return false, "authority lease is not observed"
	}})
	config := observability.CollectorConfig{Cell: runtime.cell, Member: runtime.member, Role: runtime.role,
		Registry: runtime.registry, Health: runtime.health, Filesystems: filesystems,
		Authority:   func() observability.AuthorityView { return authorityView(observed.authority.Current()) },
		NATS:        observed.nats.Observe,
		Delivery:    delivery.View,
		KVSnapshots: observed.kvSnapshots,
		OCI:         oci.APIView,
	}
	config.Links = func() []observability.RegionLinkProbe {
		if observed.linkProbes == nil {
			return nil
		}
		probes := observed.linkProbes()
		links := make([]observability.RegionLinkProbe, len(probes))
		for index, probe := range probes {
			links[index] = observability.RegionLinkProbe{Region: probe.Region, ObservedAt: probe.ObservedAt,
				Reach: probe.Reach, WAN: probe.WAN, LagGroups: probe.Lag, RTTMillis: probe.RoundTripMS}
		}
		return links
	}
	if observed.placements != nil {
		store := observed.placements
		config.Placement = func(ctx context.Context) (observability.PlacementView, error) {
			return placement.Summarize(ctx, store)
		}
	}
	if files := observed.credentials; len(files) > 0 {
		var mu sync.Mutex
		var last string
		config.Credentials = func() ([]observability.CredentialView, error) {
			credentials, err := maintenance.Scan(files)
			// The snapshot carries only an error class; log which file
			// failed, once per change. Roles and paths are not secret.
			text := ""
			if err != nil {
				text = err.Error()
			}
			mu.Lock()
			if text != "" && text != last {
				slog.WarnContext(ctx, "credential expiry scan incomplete", observability.ComponentKey, "maintenance", "error", err)
			}
			last = text
			mu.Unlock()
			return credentials, err
		}
	}
	collector, err := observability.NewCollector(config)
	if err != nil {
		return err
	}
	runtime.attachSnapshots(collector)
	// Cell-wide aggregation is telemetry too: a subscription the broker
	// refuses (for example credentials without the obs grant) leaves this
	// member's own view in place instead of stopping the controller.
	if _, err := observability.ServeSnapshots(ctx, observed.nats.Conn(), runtime.cell, collector); err != nil {
		slog.WarnContext(ctx, "cell-wide observability unavailable; serving the local view only",
			observability.ComponentKey, "observability", "error", err)
		runtime.attachJournal(ctx, observed, collector, nil)
		return nil
	}
	aggregator, err := observability.NewAggregator(observed.nats.Conn(), runtime.cell, observed.brokerIDs,
		observability.DefaultAggregationTimeout)
	if err != nil {
		slog.WarnContext(ctx, "cell-wide observability unavailable; serving the local view only",
			observability.ComponentKey, "observability", "error", err)
		runtime.attachJournal(ctx, observed, collector, nil)
		return nil
	}
	if runtime.server != nil {
		runtime.server.HandleCluster(aggregator)
	}
	runtime.attachBoards(func() { runtime.cluster = aggregator })
	runtime.attachJournal(ctx, observed, collector, aggregator)
	return nil
}

func authorityView(snapshot authority.Snapshot) observability.AuthorityView {
	return observability.AuthorityView{Leader: snapshot.Leader, Ready: snapshot.Ready,
		CanMutate: snapshot.CanMutate(), OwnerID: snapshot.OwnerID, Epoch: snapshot.Epoch,
		Revision: snapshot.Revision, ExpiresAt: snapshot.ExpiresAt, ObservedAt: snapshot.ObservedAt,
		Reason: snapshot.Reason}
}

func NewServer(config Config, deps ServerDeps) (*Server, error) {
	if err := config.Validate(); err != nil {
		return nil, err
	}
	var token []byte
	if config.BearerTokenFile != "" {
		var err error
		if token, err = readBearerToken(config.BearerTokenFile); err != nil {
			return nil, err
		}
	}
	return newServer(config, token, deps)
}

// NewTokenServer is NewServer with the bearer token itself instead of
// bearer_token_file, for a listener whose token is read from Vault. The
// token is required whatever the address.
func NewTokenServer(config Config, token string, deps ServerDeps) (*Server, error) {
	checked, err := checkBearerToken([]byte(token))
	if err != nil {
		return nil, err
	}
	// The token stands in for the file Validate requires off loopback.
	config.BearerTokenFile = "token"
	if err := config.Validate(); err != nil {
		return nil, err
	}
	return newServer(config, checked, deps)
}

func newServer(config Config, token []byte, deps ServerDeps) (*Server, error) {
	if deps.Registry == nil || deps.Health == nil {
		return nil, errors.New("observability server requires a registry and health checks")
	}
	manager := &sessions{secure: config.TLSCertFile != ""}
	if deps.LocalSessions {
		manager.local = make(map[string]struct{})
	}
	server := &Server{mux: http.NewServeMux(), deps: deps, sessions: manager, token: token}
	server.catalog = &metricCatalog{registry: deps.Registry}
	if deps.Sessions != nil && token != nil {
		ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
		defer cancel()
		if err := server.SetSessionStore(ctx, deps.Sessions); err != nil {
			return nil, err
		}
	}
	server.mux.HandleFunc("GET /healthz", func(writer http.ResponseWriter, _ *http.Request) {
		writePlain(writer, http.StatusOK, "ok\n")
	})
	server.mux.HandleFunc("GET /readyz", server.readyz)
	server.Handle("GET /metrics", http.HandlerFunc(server.metrics))
	server.HandleAuthenticated("GET /v1/metrics/catalog", http.HandlerFunc(server.metricCatalogHTTP))
	if deps.Snapshots != nil {
		server.HandleSnapshots(deps.Snapshots)
	}
	if deps.Cluster != nil {
		server.HandleCluster(deps.Cluster)
	}
	if deps.Events != nil {
		server.Handle("GET /v1/events", http.HandlerFunc(server.events))
	}
	return server, nil

// ServeHTTP lets tests and an embedding mux exercise the routes directly.
func (server *Server) ServeHTTP(writer http.ResponseWriter, request *http.Request) {
	// A proxy hop would make the bind address meaningless as an access
	// control, exactly as for the host enrollment listener.
	if request.Header.Get("Forwarded") != "" || request.Header.Get("X-Forwarded-For") != "" ||
		request.Header.Get("X-Real-IP") != "" {
		writePlain(writer, http.StatusBadRequest, "proxied requests are not accepted\n")
		return
	}
	// Without a token the loopback bind is the only control, and DNS
	// rebinding defeats it for any route reachable under a hostname. Every
	// route of a tokenless listener, not only the dashboard's, therefore
	// requires an IP literal or localhost as the Host.
	if server.token == nil && !LiteralHost(request.Host) {
		writePlain(writer, http.StatusMisdirectedRequest, "address this listener by IP or localhost\n")
		return
	}
	server.mux.ServeHTTP(writer, request)
}

func (server *Server) authenticate(next http.Handler) http.Handler {
	return http.HandlerFunc(func(writer http.ResponseWriter, request *http.Request) {
		if server.token != nil && !bearerMatches(request.Header.Get("Authorization"), server.token) {
			authenticated := false
			if request.Header.Get("Authorization") == "" && server.loginMounted.Load() {
				var err error
				authenticated, err = server.sessions.authenticated(request)
				if err != nil {
					writePlain(writer, http.StatusServiceUnavailable, "session storage unavailable\n")
					return
				}
			}
			if !authenticated {
				if server.loginMounted.Load() && wantsLoginPage(request) {
					http.Redirect(writer, request, "/login?next="+url.QueryEscape(LocalRedirectPath(request.URL.RequestURI())),
						http.StatusSeeOther)
					return
				}
				writer.Header().Set("WWW-Authenticate", `Bearer realm="ts-orch"`)
				writePlain(writer, http.StatusUnauthorized, "unauthorized\n")
				return
			}
		}
		if server.token != nil && server.loginMounted.Load() && request.Header.Get("Authorization") == "" {
			if cookie, err := request.Cookie(SessionCookieName); err == nil {
				http.SetCookie(writer, server.sessions.cookie(cookie.Value))
			}
		}
		next.ServeHTTP(writer, request)
	})
}

func (server *Server) Start(ctx context.Context, config Config) (<-chan error, error) {
	address, err := ValidateListenAddress(config.Address())
	if err != nil {
		return nil, err
	}
	// The token was read by NewServer from its own config; never let a
	// different Start config widen a tokenless server onto a network address.
	if !address.Addr().IsLoopback() && server.token == nil {
		return nil, errors.New("a non-loopback observability listener requires bearer_token_file")
	}
	var tlsConfig *tls.Config
	if config.TLSCertFile != "" {
		certificate, err := tls.LoadX509KeyPair(config.TLSCertFile, config.TLSKeyFile)
		if err != nil {
			return nil, fmt.Errorf("load observability TLS: %w", err)
		}
		tlsConfig = &tls.Config{MinVersion: tls.VersionTLS13, Certificates: []tls.Certificate{certificate}}
	}
	listener, err := (&net.ListenConfig{}).Listen(ctx, "tcp", address.String())
	if err != nil {
		return nil, err
	}
	if tlsConfig != nil {
		listener = tls.NewListener(listener, tlsConfig)
	}
	// No WriteTimeout: dashboard streams are long-lived. Headers and request
	// bodies are bounded as for the host enrollment listener.
	server.http = &http.Server{Handler: TraceHTTP(server), ReadHeaderTimeout: 5 * time.Second,
		ReadTimeout: 10 * time.Second, IdleTimeout: time.Minute, MaxHeaderBytes: 4096}
	server.listen = listener
	if server.token != nil {
		cleanupCtx, cancel := context.WithCancel(ctx)
		server.reclaimCancel, server.reclaimDone = cancel, make(chan struct{})
		go func() {
			defer close(server.reclaimDone)
			server.sessions.retryCleanup(cleanupCtx)
		}()
	}
	result := make(chan error, 1)
	go func() {
		err := server.http.Serve(listener)
		if errors.Is(err, http.ErrServerClosed) {
			err = nil
		}
		result <- err
	}()
	context.AfterFunc(ctx, func() { _ = server.Close() })
	return result, nil
}

func (config Config) Address() string {
	if config.ListenAddress == "" {
		return DefaultListenAddress
	}
	return config.ListenAddress
}

// Validate checks the listener address, token and TLS pairing and the log
// settings without reading any file.
func (config Config) Validate() error {
	if _, _, err := ParseLogConfig(config.LogFormat, config.LogLevel); err != nil {
		return err
	}
	if (config.TLSCertFile == "") != (config.TLSKeyFile == "") {
		return errors.New("observability TLS requires both a certificate and a key file")
	}
	address, err := ValidateListenAddress(config.Address())
	if err != nil {
		return err
	}
	if !address.Addr().IsLoopback() && config.BearerTokenFile == "" {
		return errors.New("a non-loopback observability listener requires bearer_token_file")
	}
	return nil
}

// ValidateListenAddress accepts only a literal private IP and a non-zero
// port. Wildcard, public, link-local and multicast addresses are rejected,
// so metrics never reach a public interface by configuration mistake.
func ValidateListenAddress(raw string) (netip.AddrPort, error) {
	address, err := netip.ParseAddrPort(raw)
	if err != nil || address.Port() == 0 || address.Addr().Zone() != "" ||
		address.String() != raw {
		return netip.AddrPort{}, fmt.Errorf("observability listen address %q must be a literal IP:port", raw)
	}
	ip := address.Addr().Unmap()
	if ip.IsUnspecified() || ip.IsMulticast() || ip.IsLinkLocalUnicast() {
		return netip.AddrPort{}, errors.New("observability listener must bind one private address, not a wildcard")
	}
	if !ip.IsLoopback() && !ip.IsPrivate() {
		return netip.AddrPort{}, errors.New("observability listener must bind loopback or a private VCN or NetBird address")
	}
	return address, nil
}

func readBearerToken(path string) ([]byte, error) {
	file, err := os.Open(path)
	if err != nil {
		return nil, fmt.Errorf("open observability bearer token: %w", err)
	}
	defer file.Close()
	info, err := file.Stat()
	if err != nil || !info.Mode().IsRegular() || info.Mode().Perm()&0o077 != 0 {
		return nil, errors.New("observability bearer token must be a private regular file")
	}
	data, err := io.ReadAll(io.LimitReader(file, maxBearerTokenBytes+1))
	if err != nil {
		return nil, err
	}
	return checkBearerToken(data)
}

func (manager *sessions) issue(ctx context.Context) (string, error) {
	ctx, cancel := context.WithTimeout(ctx, sessionStoreTimeout)
	defer cancel()
	binding := manager.binding.Load()
	if binding == nil && manager.local == nil {
		return "", errors.New("dashboard session store unavailable")
	}
	if binding != nil {
		var err error
		binding, err = manager.reconcile(ctx, binding)
		if err != nil {
			return "", err
		}
		if binding == nil {
			return "", errors.New("dashboard token retired")
		}
	}
	var raw [32]byte
	if _, err := rand.Read(raw[:]); err != nil {
		return "", err
	}
	encoded := base64.RawURLEncoding.EncodeToString(raw[:])
	if binding == nil {
		manager.mu.Lock()
		defer manager.mu.Unlock()
		if len(manager.local) >= maxSessions {
			return "", errSessionCapacity
		}
		value := "v3.0." + encoded
		manager.local[sessionHash(value)] = struct{}{}
		return value, nil
	}
	// Fixed CAS-allocated slots enforce capacity across all controllers,
	// including simultaneous logins. Only the cookie's digest is stored.
	start := (int(raw[0])<<8 | int(raw[1])) % maxSessions
	const probes = 8
	var occupied [maxSessions]bool
	for offset := range maxSessions + probes {
		if offset == probes {
			var err error
			occupied, err = binding.occupied(ctx)
			if err != nil {
				return "", err
			}
		}
		slot := (start + offset) % maxSessions
		if occupied[slot] {
			continue
		}
		value := "v3." + strconv.Itoa(slot) + "." + encoded
		revision, err := binding.store.kv.Create(ctx, binding.key(value), []byte(sessionHash(value)))
		if errors.Is(err, jetstream.ErrKeyExists) {
			occupied[slot] = true
			continue
		}
		if err != nil {
			return "", errors.Join(err, manager.rollback(ctx, sessionRollback{store: binding.store, key: binding.key(value), hash: sessionHash(value)}))
		}
		// Rotation can finish cleanup before this in-flight allocation commits.
		current, err := binding.current(ctx)
		if err != nil || !current {
			if err == nil {
				err = errors.New("dashboard token retired")
			}
			return "", errors.Join(err, manager.rollback(ctx, sessionRollback{store: binding.store, key: binding.key(value), revision: revision}))
		}
		return value, nil
	}
	return "", errSessionCapacity

func (manager *sessions) valid(ctx context.Context, value string) (bool, error) {
	if !validSessionValue(value) {
		return false, nil
	}
	ctx, cancel := context.WithTimeout(ctx, sessionStoreTimeout)
	defer cancel()
	binding := manager.binding.Load()
	if binding == nil {
		manager.mu.Lock()
		defer manager.mu.Unlock()
		if manager.local == nil {
			return false, errors.New("dashboard session store unavailable")
		}
		_, ok := manager.local[sessionHash(value)]
		return ok, nil
	}
	// Uncached leader reads prevent stale grants after another controller's
	// logout or token rotation; outages must not authorize cached sessions.
	entry, err := binding.store.get(ctx, binding.key(value))
	if errors.Is(err, nats.ErrMsgNotFound) || errors.Is(err, jetstream.ErrKeyNotFound) ||
		err == nil && subtle.ConstantTimeCompare(entry.Data, []byte(sessionHash(value))) != 1 {
		// Only a miss needs reconciliation; successful reads keep the final fence.
		latest, reconcileErr := manager.reconcile(ctx, binding)
		if reconcileErr != nil || latest == nil || latest == binding {
			return false, reconcileErr
		}
		binding = latest
		entry, err = binding.store.get(ctx, binding.key(value))
	}
	if errors.Is(err, nats.ErrMsgNotFound) || errors.Is(err, jetstream.ErrKeyNotFound) {
		return false, nil
	}
	if err != nil {
		return false, err
	}
	if subtle.ConstantTimeCompare(entry.Data, []byte(sessionHash(value))) != 1 {
		return false, nil
	}
	// Rotation can commit while the session read is in flight, before cleanup.
	return binding.current(ctx)
}

func (manager *sessions) revoke(ctx context.Context, value string) error {
	if !validSessionValue(value) {
		return nil
	}
	ctx, cancel := context.WithTimeout(ctx, sessionStoreTimeout)
	defer cancel()
	binding := manager.binding.Load()
	if binding == nil {
		manager.mu.Lock()
		defer manager.mu.Unlock()
		if manager.local == nil {
			return errors.New("dashboard session store unavailable")
		}
		delete(manager.local, sessionHash(value))
		return nil

func (manager *sessions) authenticated(request *http.Request) (bool, error) {
	cookie, err := request.Cookie(SessionCookieName)
	if err != nil {
		return false, nil
	}
	return manager.valid(request.Context(), cookie.Value)
}

// HandleLogin mounts the browser login routes of the dashboard. page renders
// GET /login; POST /login exchanges the bearer token for a session cookie and
// POST /logout clears it. Without HandleLogin, or on a tokenless loopback
// listener, browsers have no session path and only the bearer header works.
func (server *Server) HandleLogin(page http.Handler) {
	server.loginMounted.Store(true)
	server.mux.Handle("GET /login", http.HandlerFunc(func(writer http.ResponseWriter, request *http.Request) {
		if server.token == nil {
			http.Redirect(writer, request, LocalRedirectPath(request.URL.Query().Get("next")), http.StatusSeeOther)
			return
		}
		authenticated, err := server.sessions.authenticated(request)
		if err != nil {
			writePlain(writer, http.StatusServiceUnavailable, "session storage unavailable\n")
			return
		}
		if authenticated {
			http.Redirect(writer, request, LocalRedirectPath(request.URL.Query().Get("next")), http.StatusSeeOther)
			return
		}
		page.ServeHTTP(writer, request)
	}))
	server.mux.HandleFunc("POST /login", server.login)
	server.mux.HandleFunc("POST /logout", func(writer http.ResponseWriter, request *http.Request) {
		if !sameOriginForm(request) {
			writePlain(writer, http.StatusForbidden, "cross-site request refused\n")
			return
		}
		// Revoke the session itself, not only this browser's cookie: a
		// copied cookie stops working too.
		if cookie, err := request.Cookie(SessionCookieName); err == nil {
			if err := server.sessions.revoke(request.Context(), cookie.Value); err != nil {
				writePlain(writer, http.StatusServiceUnavailable, "session revocation unavailable\n")
				return
			}
		}
		http.SetCookie(writer, server.sessions.cookie(""))
		http.Redirect(writer, request, "/login", http.StatusSeeOther)
	})
}

func (server *Server) login(writer http.ResponseWriter, request *http.Request) {
	if server.token == nil {
		http.Redirect(writer, request, "/", http.StatusSeeOther)
		return
	}
	if !sameOriginForm(request) {
		writePlain(writer, http.StatusForbidden, "cross-site request refused\n")
		return
	}
	request.Body = http.MaxBytesReader(writer, request.Body, maxLoginFormSize)
	if err := request.ParseForm(); err != nil {
		writePlain(writer, http.StatusBadRequest, "invalid login form\n")
		return
	}
	next := LocalRedirectPath(request.PostForm.Get("next"))
	presented := strings.TrimSpace(request.PostForm.Get("token"))
	if subtle.ConstantTimeCompare([]byte(presented), server.token) != 1 {
		http.Redirect(writer, request, "/login?failed=1&next="+url.QueryEscape(next), http.StatusSeeOther)
		return
	}
	ctx, cancel := context.WithTimeout(request.Context(), sessionStoreTimeout)
	defer cancel()
	if cookie, err := request.Cookie(SessionCookieName); err == nil {
		valid, err := server.sessions.valid(ctx, cookie.Value)
		if err != nil {
			writePlain(writer, http.StatusServiceUnavailable, "session storage unavailable\n")
			return
		}
		if valid {
			http.SetCookie(writer, server.sessions.cookie(cookie.Value))
			http.Redirect(writer, request, next, http.StatusSeeOther)
			return
		}
	}
	value, err := server.sessions.issue(ctx)
	if err != nil {
		if errors.Is(err, errSessionCapacity) {
			writePlain(writer, http.StatusServiceUnavailable, "dashboard session limit reached; sign out in another browser or rotate the dashboard token\n")
			return
		}
		writePlain(writer, http.StatusServiceUnavailable, "session storage unavailable\n")
		return
	}
	http.SetCookie(writer, server.sessions.cookie(value))
	http.Redirect(writer, request, next, http.StatusSeeOther)
}

func (dashboard *Dashboard) Mount(mounter Mounter) {
	mounter.HandleStatic("GET /assets/{hash}/{file}", http.HandlerFunc(serveAsset))
	mounter.HandleLogin(dashboard.guard(http.HandlerFunc(dashboard.login)))
	for _, page := range slices.Concat(pages, detailPages) {
		mounter.Handle("GET "+page.path(), dashboard.guard(dashboard.pageHandler(page)))
		mounter.Handle("GET "+page.streamPath(), dashboard.guard(dashboard.streamHandler(page)))
	}
	mounter.Handle("POST /capacity/budget", dashboard.guard(http.HandlerFunc(dashboard.setBudget)))
}

func freeLoopbackAddress(t *testing.T) string {
	t.Helper()
	listener, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		t.Fatal(err)
	}
	address := listener.Addr().String()
	_ = listener.Close()
	return address
}

