func newAuthenticatedNATS(t *testing.T, cell string, brokers ...string) *authenticatedNATS {
	t.Helper()
	a := &authenticatedNATS{root: t.TempDir(), cell: cell, brokers: slices.Clone(brokers)}
	a.tls, a.routePassword = testR3TLSMaterial(t, a.root)
	operator, err := nkeys.CreateOperator()
	if err != nil {
		t.Fatal(err)
	}
	system, err := nkeys.CreateAccount()
	if err != nil {
		t.Fatal(err)
	}
	a.account, err = nkeys.CreateAccount()
	if err != nil {
		t.Fatal(err)
	}
	operatorID, _ := operator.PublicKey()
	systemID, _ := system.PublicKey()
	a.cellID, _ = a.account.PublicKey()
	operatorClaim := jwt.NewOperatorClaims(operatorID)
	operatorClaim.SystemAccount = systemID
	operatorJWT, err := operatorClaim.Encode(operator)
	if err != nil {
		t.Fatal(err)
	}
	systemJWT, err := jwt.NewAccountClaims(systemID).Encode(operator)
	if err != nil {
		t.Fatal(err)
	}
	cellClaim := jwt.NewAccountClaims(a.cellID)
	cellClaim.Limits.JetStreamLimits = jwt.JetStreamLimits{MemoryStorage: 256 << 20, DiskStorage: 8 << 30, Streams: 100, Consumer: 100}
	a.cellJWT, err = cellClaim.Encode(operator)
	if err != nil {
		t.Fatal(err)
	}
	write := func(name, raw string) string {
		path := filepath.Join(a.root, name)
		if err := os.WriteFile(path, []byte(raw), 0o600); err != nil {
			t.Fatal(err)
		}
		return path
	}
	a.operatorFile = write("operator.jwt", operatorJWT)
	a.systemFile = write("system.jwt", systemJWT)
	a.cellFile = write("cell.jwt", a.cellJWT)
	systemUser, systemCredentials := testBrokerJWTUser(t, a.root, "system.creds", system, systemID,
		[]string{"$SYS.REQ.ACCOUNT." + a.cellID + ".CLAIMS.UPDATE"}, nil)
	systemClaim, err := jwt.DecodeUserClaims(testDecoratedJWT(t, systemCredentials))
	if err != nil {
		t.Fatal(err)
	}
	systemClaim.Sub.Allow = jwt.StringList{protocol.InboxPrefix(cell, systemUser) + ".>"}
	a.systemCredentials = testBrokerJWTUserWithClaim(t, a.root, "system.creds", system, systemClaim)
	public, _ := testEd25519(t, a.root, "ticket.key")
	a.ticketPrivateFile = filepath.Join(a.root, "ticket.key")
	a.ticketPublicFile = write("ticket.pub", base64.StdEncoding.EncodeToString(public))
	return a
}

func (a *authenticatedNATS) config(t *testing.T, cfg natscell.Config) natscell.Config {
	t.Helper()
	if cfg.Cell != "" && cfg.Cell != a.cell {
		t.Fatalf("fixture cell %q differs from client cell %q", a.cell, cfg.Cell)
	}
	cfg.Cell = a.cell
	if cfg.Instance == "" {
		cfg.Instance = "one"
	}
	if cfg.Replicas == 0 {
		cfg.Replicas = 1
	}
	role := cfg.ClientRole
	if role == "" {
		role = "controller"
	}
	var user nkeys.KeyPair
	var err error
	if cfg.NKeySeedFile != "" {
		seed, readErr := os.ReadFile(cfg.NKeySeedFile)
		if readErr != nil {
			t.Fatal(readErr)
		}
		user, err = nkeys.FromSeed(seed)
		clear(seed)
	} else if cfg.CredentialsFile != "" {
		credentials, readErr := os.ReadFile(cfg.CredentialsFile)
		if readErr != nil {
			t.Fatal(readErr)
		}
		user, err = nkeys.ParseDecoratedUserNKey(credentials)
		clear(credentials)
	} else {
		user, err = nkeys.CreateUser()
	}
	if err != nil {
		t.Fatal(err)
	}
	defer user.Wipe()
	public, err := user.PublicKey()
	if err != nil {
		t.Fatal(err)
	}
	claim := jwt.NewUserClaims(public)
	claim.IssuerAccount = a.cellID
	claim.Sub.Allow = jwt.StringList{protocol.InboxPrefix(a.cell, public) + ".>"}
	switch role {
	case "controller":
		claim.Pub.Allow = natscell.ControllerPublishes(a.cell)
		claim.Pub.Allow.Add(natscell.GlobalControllerPublishes()...)
		claim.Pub.Allow.Add(natscell.GlobalControllerRequests()...)
		claim.Pub.Allow.Add("$JS.ACK.>")
		claim.Sub.Allow.Add(natscell.ControllerSubscriptions(a.cell)...)
		claim.Sub.Allow.Add(natscell.GlobalControllerRequests()...)
		claim.Sub.Allow.Add(protocol.ObservabilityGrant(a.cell), protocol.Broker(a.cell, "ticket", ">"), protocol.Broker(a.cell, "fence", cfg.Instance))
		claim.Resp = &jwt.ResponsePermission{MaxMsgs: 1, Expires: 5 * time.Second}
	case "operator":
		claim.Pub.Allow = natscell.BrokerOperatorPublishPermissions(a.cell)
	case "host":
		claim.Pub.Allow = jwt.StringList{protocol.AgentObservation(a.cell, public, "*")}
	default:
		t.Fatalf("unsupported authenticated fixture role %q", role)
	}
	cfg.CredentialsFile = testBrokerJWTUserWithKey(t, a.root, cfg.Instance+"-"+public+".creds", a.account, user, claim)
	cfg.NKeySeedFile = ""
	cfg.TLS = a.tls
	cfg.URL = strings.ReplaceAll(cfg.URL, "nats://", "tls://")
	if cfg.Embedded != nil {
		embedded := *cfg.Embedded
		cfg.Embedded = &embedded
		embedded.Users = nil
		embedded.TLS, embedded.RouteTLS = a.tls, a.tls
		embedded.RouteUser, embedded.RoutePasswordFile = "integration-route", a.routePassword
		embedded.OperatorJWTFile, embedded.SystemJWTFile, embedded.CellJWTFile = a.operatorFile, a.systemFile, a.cellFile
		embedded.SystemCredentialsFile, embedded.TicketPublicKeyFile = a.systemCredentials, a.ticketPublicFile
		embedded.BrokerIDs = slices.Clone(a.brokers)
		if len(embedded.BrokerIDs) == 0 {
			embedded.BrokerIDs = []string{cfg.Instance}
		}
		if embedded.StoreDir == "" {
			embedded.StoreDir = filepath.Join(a.root, cfg.Instance)
		}
		if embedded.Host == "" {
			embedded.Host = "127.0.0.1"
		}
		if embedded.Port == 0 {
			embedded.Port = reserveControllerPort(t)
		}
	}
	return cfg
}

func (a *authenticatedNATS) start(t *testing.T, ctx context.Context, cfg natscell.Config) (*natscell.Runtime, error) {
	t.Helper()
	runtime, err := natscell.Start(ctx, a.config(t, cfg))
	if err != nil {
		return nil, err
	}
	t.Cleanup(func() { _ = runtime.Close() })
	if cfg.Embedded != nil {
		if err := runtime.ApplyCellClaim(ctx, 1, a.cellJWT); err != nil {
			return nil, fmt.Errorf("apply fixture claim: %w", err)
		}
		if err := runtime.Bridge().OpenUntil(1, a.cellJWT, time.Now().Add(5*time.Minute)); err != nil {
			return nil, fmt.Errorf("open fixture bridge: %w", err)
		}
	}
	return runtime, nil
}

func Start(ctx context.Context, cfg Config) (_ *Runtime, err error) {
	return start(ctx, cfg, false)
}

func start(ctx context.Context, cfg Config, identityRekey bool) (_ *Runtime, err error) {
	if err := cfg.validate(); err != nil {
		return nil, err
	}
	r := &Runtime{cell: cfg.Cell}
	defer func() {
		if err != nil {
			_ = r.Close()
		}
	}()
	if cfg.Embedded != nil {
		options, optionsErr := serverOptionsForStart(cfg, identityRekey)
		if optionsErr != nil {
			return nil, optionsErr
		}
		r.server, err = server.NewServer(options)
		if err != nil {
			return nil, fmt.Errorf("create embedded NATS: %w", err)
		}
		if err := pinNodeIdentity(cfg.Embedded.StoreDir, cfg.Cell, cfg.Instance, r.server.NodeName()); err != nil {
			return nil, fmt.Errorf("pin embedded NATS Raft identity: %w", err)
		}
		r.server.SetLoggerV2(natsLogger{}, false, false, false)
		r.serverName = options.ServerName
		for _, id := range cfg.Embedded.BrokerIDs {
			r.brokerNames = append(r.brokerNames, ServerName(cfg.Cell, id))
		}
		go r.server.Start()
		if !serverReady(ctx, r.server) {
			return nil, errors.New("embedded NATS did not become ready")
		}
		cfg.URL = r.server.ClientURL()
		r.resolver = options.AccountResolver.(*accountResolver)
		r.operator = options.TrustedOperators[0]
		if _, err := r.server.LookupAccount(r.resolver.cell); err != nil {
			return nil, fmt.Errorf("load regional cell account: %w", err)
		}
	}
	options, err := clientOptions(cfg)
	if err != nil {
		return nil, err
	}
	if cfg.Embedded != nil {
		options = append(options, nats.InProcessServer(r.server))
	}
	if cfg.ClientRole == "host" {
		// A blackholed peer must be detected well inside the host's 25-second
		// execution window. nats.go otherwise waits two minutes between PINGs.
		options = append(options,
			nats.PingInterval(2*time.Second), nats.MaxPingsOutstanding(2),
			nats.ReconnectWait(500*time.Millisecond),
			nats.DisconnectErrHandler(func(conn *nats.Conn, cause error) {
				r.logHostConnection("disconnected", conn, cause)
			}),
			nats.ReconnectHandler(func(conn *nats.Conn) {
				r.logHostConnection("reconnected", conn, nil)
			}),
		)
	}
	connectCtx, cancel := context.WithTimeout(ctx, 15*time.Second)
	defer cancel()
	connected := make(chan struct{})
	var connectErr, forwardErr error
	go func() {
		connectURL := cfg.URL
		if cfg.Embedded == nil {
			if len(cfg.OperatorForward) != 0 {
				var selected string
				selected, _, forwardErr = operatorForwarding(cfg)
				if forwardErr != nil {
					close(connected)
					return
				}
				connectURL = selected
			}
			connectURL = bridgeClientURLs(connectURL)
		}
		r.conn, connectErr = nats.Connect(connectURL, options...)
		close(connected)
	}()
	select {
	case <-connectCtx.Done():
		// nats.Connect has a bounded timeout of its own; wait for the goroutine
		// before cleaning up to avoid a late client after server shutdown.
		<-connected
		if forwardErr != nil {
			return nil, forwardErr
		}
		return nil, unavailable{connectCtx.Err()}
	case <-connected:
	}
	if forwardErr != nil {
		return nil, forwardErr
	}
	if connectErr != nil {
		err := fmt.Errorf("connect regional NATS: %w", connectErr)
		if errors.Is(connectErr, nats.ErrAuthorization) {
			// The brokers answered and refused these credentials.
			return nil, err
		}
		return nil, unavailable{err}
	}
	if cfg.Embedded != nil {
		systemCfg := cfg
		systemCfg.NKeySeedFile = ""
		systemCfg.CredentialsFile = cfg.Embedded.SystemCredentialsFile
		systemOptions, optionErr := clientOptions(systemCfg)
		if optionErr != nil {
			return nil, fmt.Errorf("system account client: %w", optionErr)
		}
		systemOptions = append(systemOptions, nats.InProcessServer(r.server))
		r.systemConn, err = nats.Connect(cfg.URL, systemOptions...)
		if err != nil {
			return nil, fmt.Errorf("connect internal system account: %w", err)
		}
		r.brokerTLS, err = NewReloadingTLS(cfg.Embedded.TLS, "listener")
		if err != nil {
			return nil, err
		}
		if !identityRekey {
			r.bridge, err = startBridge(r.server, net.JoinHostPort(cfg.Embedded.Host, fmt.Sprint(cfg.Embedded.Port)),
				r.brokerTLS.ServerConfig(), r.resolver.cell)
			if err != nil {
				return nil, err
			}
		}
	}
	if cfg.ClientRole == "host" {
		r.logHostConnection("connected", r.conn, nil)
	}
	r.js, err = jetstream.New(r.conn)
	if err != nil {
		return nil, fmt.Errorf("open regional JetStream: %w", err)
	}
	// A new R3 cell cannot elect a JetStream metadata leader until its peers
	// have also started. The app calls WaitForCluster before any mutations.
	if cfg.Replicas == 1 && cfg.ClientRole != "host" {
		infoCtx, infoCancel := context.WithTimeout(ctx, 10*time.Second)
		defer infoCancel()
		if _, err := r.js.AccountInfo(infoCtx); err != nil {
			return nil, unavailable{fmt.Errorf("regional JetStream unavailable: %w", err)}
		}
	}
	return r, nil
}

func NewLogger(output io.Writer, config LogConfig, bus *EventBus, attrs ...slog.Attr) (*slog.Logger, error) {
	config, level, err := ParseLogConfig(config.Format, config.Level)
	if err != nil {
		return nil, err
	}
	if journalStream() {
		output = journalWriter{next: output}
	}
	options := &slog.HandlerOptions{Level: level, ReplaceAttr: utcTime}
	var handler slog.Handler
	if config.Format == "logfmt" {
		handler = slog.NewTextHandler(output, options)
	} else {
		handler = slog.NewJSONHandler(output, options)
	}
	if bus != nil {
		handler = &EventTee{next: handler, bus: bus, counters: newLogCounters(), repeats: newEventRepeats()}
	}
	handler = &redactingHandler{next: handler}
	if len(attrs) > 0 {
		handler = handler.WithAttrs(attrs)
	}
	return slog.New(handler), nil
}

func (tee *EventTee) Enabled(ctx context.Context, level slog.Level) bool {
	return level >= slog.LevelInfo || tee.next.Enabled(ctx, level)
}

func (tee *EventTee) Handle(ctx context.Context, record slog.Record) error {
	if record.Level >= slog.LevelWarn || tee.marked(record) {
		event := eventFromRecord(record, tee.eventScope(), tee.groups)
		if tee.repeats.admit(event, record.Time) {
			tee.bus.Publish(event)
		}
	}
	if !tee.next.Enabled(ctx, record.Level) {
		return nil
	}
	tee.counters.count(record.Level)
	return tee.next.Handle(ctx, record)
}

func (h *redactingHandler) Handle(ctx context.Context, record slog.Record) error {
	s := logSanitizer{remaining: maxLogAttrs - 1 - h.used, truncated: h.truncated}
	if h.component.Key != "" {
		s.remaining--
	}
	clean := slog.NewRecord(record.Time, record.Level, s.text(record.Message, maxLogMessageBytes), record.PC)
	// The trace ID follows the static attributes and precedes the call's own.
	if trace := TraceID(ctx); trace != "" {
		s.remaining--
		clean.AddAttrs(slog.String(TraceIDKey, trace))
	}
	// Preserve selection and component even when ordinary attributes exhaust
	// the budget. This scan does not resolve or format application values.
	var event, component slog.Attr
	eventIndex, componentIndex := -1, -1
	index := 0
	record.Attrs(func(a slog.Attr) bool {
		if a.Key == EventKey && a.Value.Kind() == slog.KindBool {
			if event.Key == "" || !event.Value.Bool() {
				event = a
				eventIndex = index
			}
		}
		if a.Key == ComponentKey {
			component = a
			componentIndex = index
		}
		index++
		return true
	})
	// Reserve metadata capacity, but emit it in its original position so an
	// inline group and a root component keep their last-value-wins ordering.
	for _, a := range []*slog.Attr{&event, &component} {
		if a.Key != "" {
			*a, _ = s.attr(*a, h.depth, h.sensitive)
		}
	}
	index = -1
	record.Attrs(func(a slog.Attr) bool {
		index++
		if index == eventIndex {
			if event.Key != "" {
				clean.AddAttrs(event)
			}
			return true
		}
		if index == componentIndex {
			if component.Key != "" {
				clean.AddAttrs(component)
			}
			return true
		}
		if a.Key == ComponentKey || (a.Key == EventKey && eventIndex >= 0) {
			return true
		}
		if h.blocked || s.remaining <= 0 {
			s.truncated = true
			return true
		}
		if prepared, ok := s.attr(a, h.depth, h.sensitive); ok {
			clean.AddAttrs(prepared)
		}
		return true
	})
	if s.truncated {
		clean.AddAttrs(slog.Bool(logTruncatedKey, true))
	}
	return h.next.Handle(ctx, clean)
}

func (bus *EventBus) Publish(event Event) Event {
	if bus == nil {
		return event
	}
	if event.Time.IsZero() {
		event.Time = time.Now().UTC()
	}
	bus.mu.Lock()
	bus.initLocked()
	bus.sequence++
	event.Sequence = bus.sequence
	index := (bus.start + bus.size) % len(bus.ring)
	if bus.size == len(bus.ring) {
		bus.start = (bus.start + 1) % len(bus.ring)
	} else {
		bus.size++
	}
	bus.ring[index] = event
	for subscriber := range bus.subscribers {
		select {
		case subscriber.events <- event:
		default:
			bus.dropped.Add(1)
		}
	}
	bus.mu.Unlock()
	bus.published.Add(1)
	return event
}

// Recent returns up to limit of the newest events, oldest first. A
// non-positive limit returns the whole ring.
func (bus *EventBus) Recent(limit int) []Event {
	return bus.Since(0, limit)
}

// Since returns up to limit events with a sequence greater than after, oldest
// first, keeping the newest when more are available. A dashboard reconnecting
// with its last seen sequence uses it to resume without duplicates.
func (bus *EventBus) Since(after uint64, limit int) []Event {
	if bus == nil {
		return nil
	}
	bus.mu.Lock()
	defer bus.mu.Unlock()
	events := make([]Event, 0, bus.size)
	for offset := range bus.size {
		event := bus.ring[(bus.start+offset)%len(bus.ring)]
		if event.Sequence > after {
			events = append(events, event)
		}
	}
	if limit > 0 && len(events) > limit {
		events = events[len(events)-limit:]
	}
	return events
}

func validateSignedObservability(cfg Config) error {
	settings := cfg.Observability
	if err := settings.Validate(); err != nil {
		return fmt.Errorf("signed controller observability: %w", err)
	}
	address, err := netip.ParseAddrPort(settings.Address())
	if err != nil || !address.Addr().IsLoopback() && address.Addr().String() != cfg.NATS.Embedded.Host {
		return errors.New("signed observability listener must bind loopback or the signed broker address")
	}
	for _, path := range []string{settings.BearerTokenFile, settings.TLSCertFile, settings.TLSKeyFile} {
		if path != "" && (filepath.Clean(path) != path ||
			!strings.HasPrefix(path, controllerConfigDirectory+"/")) {
			return errors.New("signed observability files must live under the controller config directory")
		}
	}
	return nil
}

func LoadConfig(path string) (Config, error) {
	if path == "" {
		return Config{}, errors.New("--config is required")
	}
	info, err := os.Stat(path)
	if err != nil {
		return Config{}, fmt.Errorf("stat config: %w", err)
	}
	if info.Size() > maxConfigBytes {
		return Config{}, errors.New("config is too large")
	}
	data, err := os.ReadFile(path)
	if err != nil {
		return Config{}, fmt.Errorf("read config: %w", err)
	}
	cfg, err := decodeConfig(data)
	if err != nil {
		return Config{}, fmt.Errorf("parse config: %w", err)
	}
	if err := cfg.Observability.Validate(); err != nil {
		return Config{}, fmt.Errorf("observability config: %w", err)
	}
	if api := cfg.Controller.MachinesAPI; api != nil {
		if err := api.Validate(); err != nil {
			return Config{}, err
		}
	}
	return cfg, nil
}

// decodeConfig strictly decodes config bytes and keeps them as the config's wire.
func decodeConfig(data []byte) (Config, error) {
	var cfg Config
	if err := protocol.DecodeStrict(data, &cfg, maxConfigBytes); err != nil {
		return Config{}, err
	}
	if cfg.Version != ConfigVersion {
		return Config{}, fmt.Errorf("config version must be %d, got %d", ConfigVersion, cfg.Version)
	}
	cfg.wire = data
	return cfg, nil
}

// Package roleconfig names the signed role-configuration wire contract.
package roleconfig

// Version rejects legacy configs rather than activating formerly disabled services.
// Version 2 requires freshly produced and signed switch-free desired state;
// readers never rewrite or re-sign historical configuration bytes.
const Version = 2

func ociCostView(ctx context.Context, cell string, store *ocicost.Store, hosts []ocicost.Host, now time.Time,
) *ocicost.View {
	region, _ := oci.Region(strings.ToUpper(cell)).OCIRegion()
	report, err := store.Report(ctx)
	if err != nil {
		return &ocicost.View{Cell: cell, OCIRegion: region, Missing: err.Error()}
	}
	view := ocicost.Summarize(report, now, hosts)
	return &view
}

func (views *ociCostViews) nodes() []ocicost.Host {
	if hosts := views.pool.Load(); hosts != nil {
		return *hosts
	}
	return nil
}

// nodeCost prices the exact candidate and this region's observed resources.
// Usage forecasts remain display data; only the home ledger admits spending.
func (views *ociCostViews) nodeCost(reservations *capacityReservations, compartment string,
	recipe func(context.Context) (nodescale.Recipe, error), now func() time.Time,
) func(context.Context, nodescale.PoolState) (nodescale.Cost, error) {
	return func(ctx context.Context, state nodescale.PoolState) (cost nodescale.Cost, err error) {
		defer func() {
			if err != nil {
				reason := err.Error()
				views.pricing.Store(&reason)
				views.pool.Store(nil)
			} else {
				views.pricing.Store(nil)
			}
		}()
		if state.Pending != "" {
			return nodescale.Cost{}, fmt.Errorf("node capacity price is pending: %s", state.Pending)
		}
		shape, err := recipe(ctx)
		if err != nil {
			return nodescale.Cost{}, err
		}
		reader, proof, inventory, err := reservations.facts(ctx)
		if err != nil {
			return nodescale.Cost{}, err
		}
		cell := ""
		for _, scope := range proof.Footprint().Regions {
			if strings.EqualFold(scope.Cell, shape.Cell) {
				cell = scope.Cell
			}
		}
		quote, err := reader.Quote(ctx, proof.Footprint(), cell, compartment, shape.Capacity.Shape, float64(shape.OCPUs), float64(shape.MemoryGB),
			nodescale.BootVolumeGB)
		if err != nil {
			return nodescale.Cost{}, err
		}
		if err := quote.Validate(proof.Footprint(), cell, compartment, shape.Capacity.Shape, float64(shape.OCPUs), float64(shape.MemoryGB), nodescale.BootVolumeGB, now()); err != nil {
			return nodescale.Cost{}, err
		}
		price := quote.MonthlyCents()
		hosts := make([]ocicost.Host, 0, len(state.Instances))
		for _, instance := range state.Instances {
			hosts = append(hosts, ocicost.Host{Created: instance.Created, MonthlyCents: price})
		}
		views.pool.Store(&hosts)
		var projected uint64
		for _, resource := range inventory.Resources {
			if strings.EqualFold(resource.Cell, shape.Cell) {
				if resource.MonthlyCents > math.MaxUint64-projected {
					return nodescale.Cost{}, fmt.Errorf("regional resource cost overflows the accounting range")
				}
				projected += resource.MonthlyCents
			}
		}
		return nodescale.Cost{NodeMonthlyCents: price, ProjectedCents: projected,
			Currency: quote.Currency(), At: inventory.ObservedAt}, nil
	}
}

// view is the latest view; nil before the first refresh.
func (views *ociCostViews) view(context.Context) *ocicost.View {
	current := views.current.Load()
	if issue := views.pricing.Load(); issue != nil {
		view := ocicost.View{Cell: views.cell}
		if current != nil {
			view = *current
		}
		view.Missing = *issue
		return &view
	}
	return current
}

// rollup is the view as the dashboard rollup's cost section: nil until the
// region has a report. Per hour is the daily rate with pending hosts.
func (views *ociCostViews) rollup() *globalview.Cost {
	v := views.view(context.Background())
	if v == nil || v.Missing != "" {
		return nil
	}
	f := v.Forecast
	return &globalview.Cost{Currency: f.Currency, PerHour: float64(f.RateCents+f.PendingDailyCents) / 2400,
		MonthToDate: float64(f.MonthToDateCents) / 100, MonthForecast: float64(f.MonthEndCents) / 100,
		ObservedAt: f.ObservedAt}
}

func (r *capacityReservations) facts(ctx context.Context) (*capacityinventory.Reader, region.VerifiedInfrastructureSpend, capacityinventory.Snapshot, error) {
	if r == nil || r.spending == nil {
		return nil, region.VerifiedInfrastructureSpend{}, capacityinventory.Snapshot{}, fmt.Errorf("%w: signed infrastructure spending authority is unavailable", nodescale.ErrCapacityPending)
	}
	proof, err := r.spending.InfrastructureSpend(ctx)
	if err != nil {
		return nil, proof, capacityinventory.Snapshot{}, err
	}
	ociRegion, err := oci.Region(strings.ToUpper(r.cell)).OCIRegion()
	if err != nil {
		return nil, proof, capacityinventory.Snapshot{}, err
	}
	factory, err := instancePrincipal(ctx, ociRegion)
	if err != nil {
		return nil, proof, capacityinventory.Snapshot{}, err
	}
	reader, err := capacityinventory.New(factory)
	if err != nil {
		return nil, proof, capacityinventory.Snapshot{}, err
	}
	snapshot, err := reader.Read(ctx, proof.Footprint())
	if err == nil {
		err = snapshot.Validate(proof.Footprint(), time.Now())
	}
	return reader, proof, snapshot, err
}

func OpenStore(ctx context.Context, js jetstream.JetStream, replicas int) (*Store, error) {
	if js == nil || replicas < 1 || replicas > 5 {
		return nil, errors.New("OCI cost store requires replicated JetStream")
	}
	kv, err := js.CreateOrUpdateKeyValue(ctx, jetstream.KeyValueConfig{Bucket: Bucket, History: 1,
		MaxValueSize: maxReportBytes, MaxBytes: 1 << 20, Storage: jetstream.FileStorage, Replicas: replicas})
	if err != nil {
		return nil, fmt.Errorf("open OCI cost store: %w", err)
	}
	return &Store{kv: kv}, nil
}

// Put replaces the report. An invalid report is refused before it reaches
// the bucket, so readers never see one.
func (s *Store) Put(ctx context.Context, report Report) error {
	if err := report.Validate(); err != nil {
		return fmt.Errorf("write OCI cost report: %w", err)
	}
	wire, err := protocol.EncodeJSON(report)
	if err == nil {
		_, err = s.kv.Put(ctx, reportKey, wire)
	}
	if err != nil {
		return fmt.Errorf("write OCI cost report: %w", err)
	}
	return nil
}

// Report returns the stored report, or ErrNoReport before the first Put.
func (s *Store) Report(ctx context.Context) (Report, error) {
	entry, err := s.kv.Get(ctx, reportKey)
	if errors.Is(err, jetstream.ErrKeyNotFound) {
		return Report{}, ErrNoReport
	}
	if err != nil {
		return Report{}, fmt.Errorf("read OCI cost report: %w", err)
	}
	var report Report
	if err := protocol.DecodeStrict(entry.Value(), &report, maxReportBytes); err != nil {
		return Report{}, fmt.Errorf("read OCI cost report: %w", err)
	}
	if err := report.Validate(); err != nil {
		return Report{}, fmt.Errorf("read OCI cost report: %w", err)
	}
	return report, nil
}

func (r Report) Validate() error {
	switch {
	case r.Version != Version:
		return fmt.Errorf("%w: version %d", ErrInvalidReport, r.Version)
	case !cellPattern.MatchString(r.Cell) || r.OCIRegion == "" || len(r.OCIRegion) > maxNameBytes:
		return fmt.Errorf("%w: cell and OCI region are required", ErrInvalidReport)
	case r.Currency != "" && !currencyPattern.MatchString(r.Currency):
		return fmt.Errorf("%w: currency %q", ErrInvalidReport, r.Currency)
	case r.ObservedAt.IsZero() || !midnight(r.Through) || r.Through.After(r.ObservedAt):
		return fmt.Errorf("%w: needs an observation time after a UTC-midnight through", ErrInvalidReport)
	case len(r.Days) > maxDays || len(r.Services) > maxLines || len(r.Components) > maxLines || len(r.Prices) > maxLines:
		return fmt.Errorf("%w: more than %d days or %d lines", ErrInvalidReport, maxDays, maxLines)
	}
	var total uint64
	for index, entry := range r.Days {
		if !midnight(entry.Day) || index > 0 && !r.Days[index-1].Day.Before(entry.Day) || entry.Cents > maxCents {
			return fmt.Errorf("%w: days must be sorted unique UTC midnights within bounds", ErrInvalidReport)
		}
		total += entry.Cents
	}
	for _, lines := range [][]Line{r.Services, r.Components} {
		for index, line := range lines {
			if line.Name == "" || len(line.Name) > maxNameBytes || line.Cents > maxCents ||
				slices.ContainsFunc(lines[:index], func(other Line) bool { return other.Name == line.Name }) {
				return fmt.Errorf("%w: lines need unique bounded names", ErrInvalidReport)
			}
			total += line.Cents
		}
	}
	for _, line := range r.Components {
		if !slices.Contains(Components, line.Name) {
			return fmt.Errorf("%w: unknown component %q", ErrInvalidReport, line.Name)
		}
	}
	for index, price := range r.Prices {
		if price.SKU == "" || len(price.SKU) > maxNameBytes || index > 0 && r.Prices[index-1].SKU >= price.SKU ||
			!(price.PerUnit >= 0 && price.PerUnit <= maxUnitPrice) {
			return fmt.Errorf("%w: prices need sorted unique SKUs and unit prices within bounds", ErrInvalidReport)
		}
	}
	if r.Currency == "" && total != 0 {
		return fmt.Errorf("%w: cost without a currency", ErrInvalidReport)
	}
	return nil
}

func midnight(at time.Time) bool {
	return !at.IsZero() && at.Location() == time.UTC && at.Equal(at.Truncate(day))
}

func Summarize(report Report, now time.Time, hosts []Host) View {
	forecast := Project(report, now, hosts)
	var tagged uint64
	for _, line := range report.Components {
		tagged += line.Cents
	}
	return View{Cell: report.Cell, OCIRegion: report.OCIRegion, Forecast: forecast,
		Services:      fold(report.Services),
		Components:    fold(report.Components),
		UntaggedCents: subtractFloor(forecast.MonthToDateCents, tagged)}
}

// fold keeps the costliest lines and merges the rest into one Other line.
func fold(lines []Line) []Line {
	if len(lines) <= maxViewLines {
		return slices.Clone(lines)
	}
	out := slices.Clone(lines[:maxViewLines-1])
	other := Line{Name: "Other"}
	for _, line := range lines[maxViewLines-1:] {
		other.Cents += line.Cents
	}
	return append(out, other)
}

func subtractFloor(a, b uint64) uint64 {
	if b > a {
		return 0
	}
	return a - b
}

func Project(report Report, now time.Time, hosts []Host) Forecast {
	monthStart, monthEnd := monthBounds(now)
	nextEnd := monthEnd.AddDate(0, 1, 0)
	through := report.Through
	forecast := Forecast{Currency: report.Currency, ObservedAt: report.ObservedAt, Through: through}

	for _, entry := range report.Days {
		inMonth := !entry.Day.Before(monthStart)
		if inMonth && entry.Day.Before(monthEnd) {
			forecast.MonthToDateCents += entry.Cents
		}
		if inMonth && entry.Day.Before(through) {
			forecast.CompleteCents += entry.Cents
		}
	}

	// A new region averages only the days it has, so its rate is not diluted
	// by days before it existed.
	from := through.Add(-RateDays * day)
	if len(report.Days) > 0 && report.Days[0].Day.After(from) {
		from = report.Days[0].Day
	}
	if from.After(through) {
		from = through
	}
	n := int(through.Sub(from) / day)
	var window uint64
	for _, entry := range report.Days {
		if !entry.Day.Before(from) && entry.Day.Before(through) {
			window += entry.Cents
		}
	}
	forecast.RateFrom = from
	forecast.AveragedDays = n
	if n > 0 {
		forecast.RateCents = ceilDiv(window, uint64(n))
	}

	var pending uint64
	for _, host := range hosts {
		daily := ceilDiv(host.MonthlyCents*12, 365)
		if n == 0 {
			pending += daily
			continue
		}
		var covered int
		switch {
		case !host.Created.IsZero() && !host.Created.After(from):
			covered = n
		case host.Created.IsZero() || !host.Created.Before(through):
			covered = 0
		default:
			covered = min(n, int(through.Sub(host.Created)/day))
		}
		missed := n - covered
		pending += ceilDiv(daily*uint64(missed), uint64(n))
	}
	forecast.PendingDailyCents = pending

	start := through
	if start.Before(monthStart) {
		start = monthStart
	}
	forecast.DaysLeft = int(monthEnd.Sub(start) / day)
	perDay := forecast.RateCents + pending
	forecast.MonthEndCents = forecast.CompleteCents + perDay*uint64(forecast.DaysLeft)
	forecast.NextMonthCents = perDay * uint64(nextEnd.Sub(monthEnd)/day)
	return forecast

func testRolloutJetStream(t *testing.T) jetstream.JetStream {
	t.Helper()
	auth := newAuthenticatedNATS(t, "gru")
	runtime, err := auth.start(t, t.Context(), natscell.Config{Cell: "gru", Embedded: &natscell.Embedded{}})
	if err != nil {
		t.Fatal(err)
	}
	return runtime.JetStream()
}

func testOCIResourceStore(t *testing.T) *ociresource.KVStore {
	t.Helper()
	store, err := ociresource.OpenKVStore(t.Context(), testRolloutJetStream(t), 1)
	if err != nil {
		t.Fatal(err)
	}
