// publicLBPass publishes the TerraBase seats as the public load balancer's
// backend set, draining the seats the seat rollout holds drained. A profile
// that yields no serving seat, or seat records it cannot read, is an error,
// and the previous set stays in force.
func publicLBPass(store ociresource.Store, fencer authority.Fencer, key ociresource.Key, public OciReconcileLBConfig,
	profiles func() map[string]WorkloadProfile, drained func(context.Context) (map[string]bool, error),
) ociresource.Pass {
	return ociresource.Pass{Name: "publish-" + lb.Kind, Run: func(ctx context.Context, epoch uint64) error {
		if err := fencer.Guard(ctx, epoch); err != nil {
			return fmt.Errorf("%w: %w", ociresource.ErrFenced, err)
		}
		seats, err := drained(ctx)
		if err != nil {
			return fmt.Errorf("public load balancer: %w", err)
		}
		spec, err := public.spec(profiles(), seats)
		if err != nil {
			return err
		}
		_, err = lb.Publish(ctx, store, key, ociresource.PolicyEnforce, spec)
		return err
	}}
}

func (c OciReconcileLBConfig) key(cell string) (ociresource.Key, error) {
	key := ociresource.Key{Region: cell, Kind: lb.Kind, Name: lb.PublicTerraBase}
	if err := key.Validate(); err != nil {
		return key, err
	}
	if err := (lb.Spec{LoadBalancerID: c.LoadBalancerID, BackendSet: c.BackendSet, AllowEmpty: true}).Validate(); err != nil {
		return key, err
	}
	for i, seat := range c.Seats {
		if seat == "" || slices.Contains(c.Seats[:i], seat) {
			return key, fmt.Errorf("OCI reconcile public load balancer seat %q is empty or repeated", seat)
		}
	}
	return key, nil
}

// publicLBKey validates the signed public backend identity. Ownership always
// uses the freeform tags stamped by public-api apply.
func (c OciReconcileConfig) publicLBKey(cell string) (ociresource.Key, error) {
	return c.PublicLB.key(cell)
}

// spec derives the backend set from the current terrabase profile, with the
// seats the seat rollout holds drained. A seat the configuration lists but
// the profile does not is an error, so a typo or a removed member never
// silently shrinks the set.
func (c OciReconcileLBConfig) spec(profiles map[string]WorkloadProfile, drained map[string]bool) (lb.Spec, error) {
	profile, ok := profiles[terrabase.Role]
	if !ok {
		return lb.Spec{}, errors.New("public load balancer: the cell has no terrabase workload profile")
	}
	members, err := terrabase.ParseProfile(profile.Env)
	if err != nil {
		return lb.Spec{}, fmt.Errorf("public load balancer: %w", err)
	}
	if members.ClientPort == 0 {
		return lb.Spec{}, errors.New("public load balancer: the terrabase profile has no client listener")
	}
	spec := lb.Spec{LoadBalancerID: c.LoadBalancerID, BackendSet: c.BackendSet}
	for _, seat := range c.Seats {
		if _, ok := members.Peer(seat); !ok {
			return lb.Spec{}, fmt.Errorf("public load balancer seat %q is not in %s", seat, terrabase.EnvPeers)
		}
	}
	for _, peer := range members.Peers {
		if len(c.Seats) == 0 || slices.Contains(c.Seats, peer.Name) {
			spec.Backends = append(spec.Backends, lb.Backend{IP: peer.Address.Addr().String(), Port: members.ClientPort,
				Drain: drained[peer.Name]})
		}
	}
	return spec, nil
}

func desiredEntries[S ociresource.Validator](entries map[string]OciDesiredEntry[S]) ([]ociresource.Entry, error) {
	out := make([]ociresource.Entry, 0, len(entries))
	for _, name := range slices.Sorted(maps.Keys(entries)) {
		entry := entries[name]

		if err := entry.Spec.Validate(); err != nil {
			return nil, fmt.Errorf("OCI desired %q: %w", name, err)
		}
		out = append(out, ociresource.Entry{Name: name, Policy: ociresource.PolicyEnforce, Spec: entry.Spec})
	}
	return out, nil
}

// desiredSets validates every configured entry against the signed region
// configuration. NSG specs may only name the NSGs that configuration admits
// for member hosts.
func desiredSets(c OciDesiredConfig, cell string, region oci.RegionConfig) ([]ociDesiredSet, time.Duration, error) {
	delay := defaultOciPruneDelay
	if c.PruneDelaySeconds != 0 {
		delay = time.Duration(c.PruneDelaySeconds) * time.Second
		if delay < 0 || delay > maxOciPruneDelay {
			return nil, 0, errors.New("OCI desired prune delay must be between zero and seven days")
		}
	}
	for name, entry := range c.NSGRules {
		if !slices.Contains(region.NetworkSecurityGroupIDs, entry.Spec.NSGID) {
			return nil, 0, fmt.Errorf("OCI desired NSG %q is not admitted by the signed region configuration", name)
		}
	}
	var sets []ociDesiredSet
	add := func(kind string, entries []ociresource.Entry, err error) error {
		if err != nil {
			return err
		}
		for _, entry := range entries {
			if err := (ociresource.Key{Region: cell, Kind: kind, Name: entry.Name}).Validate(); err != nil {
				return err
			}
		}
		if len(entries) > 0 || c.Prune {
			sets = append(sets, ociDesiredSet{kind: kind, entries: entries})
		}
		return nil
	}
	nsgEntries, err := desiredEntries(c.NSGRules)
	if err := add(nsg.Kind, nsgEntries, err); err != nil {
		return nil, 0, err
	}
	listEntries, err := desiredEntries(c.SecurityLists)
	if err := add(seclist.Kind, listEntries, err); err != nil {
		return nil, 0, err
	}
	tableEntries, err := desiredEntries(c.RouteTables)
	if err := add(routetable.Kind, tableEntries, err); err != nil {
		return nil, 0, err
	}
	bucketEntries, err := desiredEntries(c.Buckets)
	if err := add(bucket.Kind, bucketEntries, err); err != nil {
		return nil, 0, err
	}
	return sets, delay, nil
}

func desiredPass(cell string, store ociresource.Store, fencer authority.Fencer, sets []ociDesiredSet, prune bool,
	delay time.Duration,
) ociresource.Pass {
	return ociresource.Pass{Name: "publish-desired", Run: func(ctx context.Context, epoch uint64) error {
		var failures []error
		for _, set := range sets {
			if err := fencer.Guard(ctx, epoch); err != nil {
				return fmt.Errorf("%w: %w", ociresource.ErrFenced, err)
			}
			result, err := ociresource.PublishSet(ctx, store, cell, set.kind, set.entries, prune, time.Now().UTC(), delay,
				func(ctx context.Context) error { return fencer.Guard(ctx, epoch) })
			if result.Published > 0 || result.Tombstoned > 0 {
				decisionlog.Record(ctx, decisionlog.Decision{
					Region: strings.ToLower(cell), Actor: decisionlog.Actor{Slice: "ociresource"},
					Kind:    decisionlog.KindOCIDesiredPublished,
					Subject: decisionlog.Subject{Kind: "oci-" + set.kind, ID: cell + "/" + set.kind},
					Summary: fmt.Sprintf("Published %d and tombstoned %d %s desired specs", result.Published,
						result.Tombstoned, set.kind),
					Reason: "The controller configuration's desired OCI specs changed.",
					Rule:   "ociresource.desired",
					Signals: []decisionlog.Signal{{Name: "published", Value: float64(result.Published)},
						{Name: "tombstoned", Value: float64(result.Tombstoned)},
						{Name: "unchanged", Value: float64(result.Unchanged)}},
					Status: decisionlog.StatusSucceeded, Epoch: epoch})
			}
			if err != nil {
				if ctx.Err() != nil {
					return err
				}
				failures = append(failures, err)
			}
		}
		return errors.Join(failures...)
	}}
}

func (r *ociReconcileRuntime) resources() insights.OCIResourceProvider {
	if r == nil || r.store == nil {
		return nil
	}
	return ociResourceStatuses{store: r.store, cell: r.cell}
}

// ociResourceStatuses adapts TS_OCI_OBSERVED to the insights provider.
type ociResourceStatuses struct {
	store ociresource.StatusLister
	cell  string
}

func (s ociResourceStatuses) OCIResources(ctx context.Context) ([]insights.OCIResource, error) {
	statuses, err := s.store.ListStatus(ctx, s.cell)
	if err != nil {
		return nil, err
	}
	out := make([]insights.OCIResource, 0, len(statuses))
	for _, status := range statuses {
		if status.Deleted {
			continue
		}
		resource := insights.OCIResource{Key: status.Key.String(), Kind: status.Key.Kind, Policy: string(status.Policy),
			Found: status.Found, InSync: status.InSync, Foreign: status.Foreign, Applied: status.Applied, Error: status.Error,
			ObservedAt: status.ObservedAt}
		for _, change := range status.Drift {
			resource.Drift = append(resource.Drift, change.Op+" "+change.Detail)
		}
		out = append(out, resource)
	}
	return out, nil
}

func (s Spec) Validate() error {
	if !strings.HasPrefix(s.LoadBalancerID, "ocid1.loadbalancer.") || s.BackendSet == "" || len(s.BackendSet) > 32 {
		return errors.New("load balancer spec requires a load balancer OCID and backend set name")
	}
	if len(s.Backends) > maxBackends {
		return errors.New("load balancer spec exceeds its backend bound")
	}
	seen := map[string]bool{}
	for _, backend := range s.Backends {
		address, err := netip.ParseAddr(backend.IP)
		if err != nil || !address.Is4() || !address.IsPrivate() {
			return fmt.Errorf("load balancer backend %q is not a private IPv4 address", backend.IP)
		}
		if backend.Port < 1 || backend.Port > 65535 {
			return errors.New("load balancer backend port is out of range")
		}
		if seen[backend.key()] {
			return errors.New("load balancer spec repeats a backend")
		}
		seen[backend.key()] = true
	}
	if !s.serves() && !s.AllowEmpty {
		return errors.New("load balancer spec has no serving backend and does not allow it")
	}
	return nil
}

// serves reports whether any backend is left in rotation.
func (s Spec) serves() bool {
	return slices.ContainsFunc(s.Backends, func(b Backend) bool { return !b.Drain })
}

func Publish(ctx context.Context, store ociresource.Store, key ociresource.Key, policy ociresource.DriftPolicy, spec Spec) (bool, error) {
	if key.Kind != Kind {
		return false, errors.New("load balancer backends must be published under the lb-backends kind")
	}
	return ociresource.Publish(ctx, store, key, policy, spec)
}

func Publish(ctx context.Context, store Store, key Key, policy DriftPolicy, spec Validator) (bool, error) {
	if err := key.Validate(); err != nil {
		return false, err
	}
	if err := spec.Validate(); err != nil {
		return false, fmt.Errorf("%s: %w", key, err)
	}
	generation := uint64(1)
	current, err := store.Get(ctx, key)
	switch {
	case errors.Is(err, ErrNotFound):
	case err != nil:
		return false, err
	default:
		if current.Tombstone != nil {
			return false, fmt.Errorf("%s: desired record is being deleted", key)
		}
		generation = current.Generation + 1
	}
	desired, err := NewDesired(key, generation, policy, spec)
	if err != nil {
		return false, err
	}
	if generation > 1 && desired.SpecDigest == current.SpecDigest && policy == current.Policy {
		return false, nil
	}
	if _, err := store.Put(ctx, desired); err != nil {
		return false, err
	}
	return true, nil

func PublishSet(ctx context.Context, store Store, region, kind string, entries []Entry, prune bool,
	now time.Time, pruneDelay time.Duration, guard func(context.Context) error,
) (SetResult, error) {
	var result SetResult
	names := make([]string, 0, len(entries))
	for _, entry := range entries {
		key := Key{Region: region, Kind: kind, Name: entry.Name}
		if err := key.Validate(); err != nil {
			return result, err
		}
		if !entry.Policy.valid() {
			return result, fmt.Errorf("%s: drift policy %q is unsupported", key, entry.Policy)
		}
		if entry.Spec == nil {
			return result, fmt.Errorf("%s: spec is missing", key)
		}
		if err := entry.Spec.Validate(); err != nil {
			return result, fmt.Errorf("%s: %w", key, err)
		}
		if slices.Contains(names, entry.Name) {
			return result, fmt.Errorf("%s: listed twice", key)
		}
		names = append(names, entry.Name)
	}
	// One entry that cannot be written (for example a name whose earlier
	// record is still being deleted) does not hold back the others.
	var failures []error
	fence := func() error {
		if guard == nil {
			return nil
		}
		if err := guard(ctx); err != nil {
			return fmt.Errorf("%w: %w", ErrFenced, err)
		}
		return nil
	}
	for _, entry := range entries {
		// Re-check authority before every write, so a controller that loses
		// leadership mid-set never publishes stale desired state.
		if err := fence(); err != nil {
			return result, err
		}
		wrote, err := Publish(ctx, store, Key{Region: region, Kind: kind, Name: entry.Name}, entry.Policy, entry.Spec)
		switch {
		case err != nil:
			if ctx.Err() != nil {
				return result, err
			}
			failures = append(failures, err)
		case wrote:
			result.Published++
		default:
			result.Unchanged++
		}
	}
	if !prune || len(failures) > 0 {
		return result, errors.Join(failures...)
	}
	if pruneDelay < 0 {
		return result, errors.New("OCI desired prune delay must not be negative")
	}
	records, err := store.List(ctx, region, kind)
	if err != nil {
		return result, err
	}
	for _, record := range records {
		if record.Tombstone != nil || slices.Contains(names, record.Key.Name) {
			continue
		}
		if err := fence(); err != nil {
			return result, err
		}
		if _, err := store.MarkDeleted(ctx, record.Key, now, now.Add(pruneDelay)); err != nil {
			return result, fmt.Errorf("%s: tombstone unlisted record: %w", record.Key, err)
		}
		result.Tombstoned++
	}
	return result, nil
}

func OpenKVStore(ctx context.Context, js jetstream.JetStream, replicas int) (*KVStore, error) {
	if js == nil || replicas < 1 || replicas > 5 {
		return nil, errors.New("OCI resource store requires JetStream and one to five replicas")
	}

	desired, err := openBucket(ctx, js, replicas, desiredBucket, "Desired OCI regional resource specs", 5)
	if err != nil {
		return nil, err
	}
	observed, err := openBucket(ctx, js, replicas, observedBucket, "Last observed OCI regional resource state and drift", 1)
	if err != nil {
		return nil, err
	}
	return &KVStore{desired: desired, observed: observed}, nil
}

func openBucket(ctx context.Context, js jetstream.JetStream, replicas int, bucket, description string, history uint8) (jetstream.KeyValue, error) {
	kv, err := js.CreateKeyValue(ctx, jetstream.KeyValueConfig{Bucket: bucket, Description: description,
		MaxValueSize: maxRecordBytes, History: history, Storage: jetstream.FileStorage, Replicas: replicas, Compression: true})
	if err == nil {
		return kv, nil
	}
	if !errors.Is(err, jetstream.ErrBucketExists) {
		return nil, fmt.Errorf("create %s bucket: %w", bucket, err)
	}
	kv, err = js.KeyValue(ctx, bucket)
	if err != nil {
		return nil, fmt.Errorf("open %s bucket: %w", bucket, err)
	}
	status, err := kv.Status(ctx)
	if err != nil {
		return nil, fmt.Errorf("inspect %s bucket: %w", bucket, err)
	}
	config := status.Config()
	if config.Replicas != replicas || config.Storage != jetstream.FileStorage || config.MaxValueSize > maxRecordBytes {
		return nil, fmt.Errorf("existing %s bucket has incompatible durability limits", bucket)
	}
	return kv, nil
}

func (s *KVStore) List(ctx context.Context, region, kind string) ([]Desired, error) {
	probe := Key{Region: region, Kind: kind, Name: "x"}
	if err := probe.Validate(); err != nil {
		return nil, err
	}
	lister, err := s.desired.ListKeysFiltered(ctx, region+"."+kind+".*")
	if err != nil {
		if errors.Is(err, jetstream.ErrNoKeysFound) {
			return nil, nil
		}
		return nil, fmt.Errorf("list OCI desired keys: %w", err)
	}
	var keys []string
	seen := make(map[string]bool)
	for key := range lister.Keys() {
		if len(keys) >= maxListedKeys {
			_ = lister.Stop()
			return nil, errors.New("OCI desired key list exceeds its safety bound")
		}
		if !seen[key] {
			seen[key] = true
			keys = append(keys, key)
		}
	}
	// The lister closes early without an error when ctx ends mid-listing;
	// a truncated listing must not look complete.
	if err := ctx.Err(); err != nil {
		return nil, fmt.Errorf("list OCI desired keys: %w", err)
	}
	slices.Sort(keys)
	records := make([]Desired, 0, len(keys))
	for _, subject := range keys {
		entry, err := s.desired.Get(ctx, subject)
		if errors.Is(err, jetstream.ErrKeyNotFound) {
			continue
		}
		if err != nil {
			return nil, fmt.Errorf("read OCI desired record: %w", err)
		}
		desired, err := decodeDesired(entry.Value(), entry.Revision())
		if err != nil {
			return nil, err
		}
		if desired.Key.subject() != subject {
			return nil, errors.New("OCI desired record key differs from its bucket key")
		}
		records = append(records, desired)
	}
	return records, nil
}

func (s *KVStore) Get(ctx context.Context, key Key) (Desired, error) {
	if err := key.Validate(); err != nil {
		return Desired{}, err
	}
	entry, err := s.desired.Get(ctx, key.subject())
	if errors.Is(err, jetstream.ErrKeyNotFound) {
		return Desired{}, ErrNotFound
	}
	if err != nil {
		return Desired{}, fmt.Errorf("read OCI desired record: %w", err)
	}
	desired, err := decodeDesired(entry.Value(), entry.Revision())
	if err != nil {
		return Desired{}, err
	}
	if desired.Key != key {
		return Desired{}, errors.New("OCI desired record key differs from its bucket key")
	}
	return desired, nil

func (s *KVStore) Put(ctx context.Context, desired Desired) (Desired, error) {
	desired.Operation = nil
	if err := desired.Validate(); err != nil {
		return Desired{}, err
	}
	wire, err := encode(desired)
	if err != nil {
		return Desired{}, err
	}
	current, err := s.Get(ctx, desired.Key)
	switch {
	case errors.Is(err, ErrNotFound):
		revision, err := s.desired.Create(ctx, desired.Key.subject(), wire)
		if errors.Is(err, jetstream.ErrKeyExists) {
			return Desired{}, ErrConflict
		}
		if err != nil {
			return Desired{}, fmt.Errorf("create OCI desired record: %w", err)
		}
		desired.Revision = revision
		return desired, nil
	case err != nil:
		return Desired{}, err
	}
	if desired.Generation <= current.Generation {
		return Desired{}, fmt.Errorf("%w: generation %d does not supersede %d", ErrConflict, desired.Generation, current.Generation)
	}
	if current.Operation != nil && current.Operation.CompletedAt.IsZero() {
		return Desired{}, fmt.Errorf("%w: previous OCI operation awaits observation", ErrConflict)
	}
	desired.Operation = nil
	wire, err = encode(desired)
	if err != nil {
		return Desired{}, err
	}
	revision, err := s.desired.Update(ctx, desired.Key.subject(), wire, current.Revision)
	if err != nil {
		return Desired{}, fmt.Errorf("%w: %w", ErrConflict, err)
	}
	desired.Revision = revision
	return desired, nil
}

func (s *KVStore) PutStatus(ctx context.Context, status Status) error {
	if err := status.Key.Validate(); err != nil {
		return err
	}
	wire, err := encode(status)
	if err != nil {
		return err
	}
	if _, err := s.observed.Put(ctx, status.Key.subject(), wire); err != nil {
		return fmt.Errorf("write OCI observed record: %w", err)
	}
	return nil
}

func (s *KVStore) GetStatus(ctx context.Context, key Key) (Status, bool, error) {
	if err := key.Validate(); err != nil {
		return Status{}, false, err
	}
	entry, err := s.observed.Get(ctx, key.subject())
	if errors.Is(err, jetstream.ErrKeyNotFound) {
		return Status{}, false, nil
	}
	if err != nil {
		return Status{}, false, fmt.Errorf("read OCI observed record: %w", err)
	}
	var status Status
	if err := json.Unmarshal(entry.Value(), &status); err != nil {
		return Status{}, false, fmt.Errorf("decode OCI observed record: %w", err)
	}
	return status, true, nil
}

// StatusLister lists the last observations of one region, for read-only
// views such as the dashboard's drift insights.
type StatusLister interface {
	ListStatus(ctx context.Context, region string) ([]Status, error)
}

// ListStatus returns every observation of region, sorted by key. A record
// that cannot be decoded fails the listing rather than hiding drift.
func (s *KVStore) ListStatus(ctx context.Context, region string) ([]Status, error) {
	if err := (Key{Region: region, Kind: "x", Name: "x"}).Validate(); err != nil {
		return nil, err
	}
	lister, err := s.observed.ListKeysFiltered(ctx, region+".*.*")
	if err != nil {
		if errors.Is(err, jetstream.ErrNoKeysFound) {
			return nil, nil
		}
		return nil, fmt.Errorf("list OCI observed keys: %w", err)
	}
	var keys []string
	for key := range lister.Keys() {
		if len(keys) >= maxListedKeys {
			_ = lister.Stop()
			return nil, errors.New("OCI observed key list exceeds its safety bound")
		}
		keys = append(keys, key)
	}
	if err := ctx.Err(); err != nil {
		return nil, fmt.Errorf("list OCI observed keys: %w", err)
	}
	slices.Sort(keys)
	keys = slices.Compact(keys)
	statuses := make([]Status, 0, len(keys))
	for _, subject := range keys {
		entry, err := s.observed.Get(ctx, subject)
		if errors.Is(err, jetstream.ErrKeyNotFound) {
			continue
		}
		if err != nil {
			return nil, fmt.Errorf("read OCI observed record: %w", err)
		}
		if len(entry.Value()) > maxRecordBytes {
			return nil, errors.New("OCI observed record exceeds its size bound")
		}
		var status Status
		if err := json.Unmarshal(entry.Value(), &status); err != nil {
			return nil, fmt.Errorf("decode OCI observed record: %w", err)
		}
		if status.Key.subject() != subject {
			return nil, errors.New("OCI observed record key differs from its bucket key")
		}
		statuses = append(statuses, status)
	}
	return statuses, nil
}

func ParseProfile(env map[string]string) (Profile, error) {
	for _, key := range hostOwned {
		if _, set := env[key]; set {
			return Profile{}, fmt.Errorf("terrabase profile must not set %s", key)
		}
	}
	profile := Profile{AdminPort: DefaultAdminPort}
	var err error
	if raw, set := env[EnvAdminPort]; set {
		if profile.AdminPort, err = parsePort(raw); err != nil {
			return Profile{}, fmt.Errorf("%s: %w", EnvAdminPort, err)
		}
	}
	if profile.PeerPort, err = parsePort(env[EnvPeerPort]); err != nil {
		return Profile{}, fmt.Errorf("%s: %w", EnvPeerPort, err)
	}
	if raw, set := env[EnvClientPort]; set {
		if profile.ClientPort, err = parsePort(raw); err != nil {
			return Profile{}, fmt.Errorf("%s: %w", EnvClientPort, err)
		}
	}
	if profile.Peers, err = ParsePeers(env[EnvPeers]); err != nil {
		return Profile{}, err
	}
	for _, peer := range profile.Peers {
		if int(peer.Address.Port()) != profile.PeerPort {
			return Profile{}, fmt.Errorf("%s: peer %s does not use %s", EnvPeers, peer.Name, EnvPeerPort)
		}
	}
	if profile.AdminPort == profile.PeerPort || profile.ClientPort == profile.AdminPort || profile.ClientPort == profile.PeerPort {
		return Profile{}, errors.New("terrabase admin, peer and client ports must differ")
	}
	return profile, nil
}

func newSpecRegistry(cfg Config, memberRole string) (*specRegistry, error) {
	r := &specRegistry{cell: cfg.NATS.Cell, fixed: map[string]WorkloadProfile{},
		signers: slices.SortedFunc(slices.Values(cfg.Controller.TrustedSigners), func(a, b TrustedSignerConfig) int {
			return strings.Compare(a.Actor, b.Actor)
		}), terraBaseCA: cfg.Controller.TerraBaseCACertFile != "",
		signedArtifactStore: cmp.Or(cfg.Controller.ArtifactStoreMaxBytes, delivery.DefaultArtifactStoreMaxBytes)}
	if cfg.NATS.Embedded != nil {
		r.artifactStoreLimit = cfg.NATS.Embedded.StoreLimitBytes() - specStoreHeadroomBytes
	}
	if _, signed := cfg.Controller.Workloads[terrabase.Role]; signed {
		r.terraBaseCA = true
	}
	if reconcile := cfg.Controller.OciReconcile; reconcile != nil {
		r.signedDesired, r.publicLB = reconcile.Desired, reconcile.PublicLB
	}
	if memberRole != "" {
		r.reserved = append(r.reserved, memberRole)
	}
	autoscaleConfig := cfg.Controller.Autoscale
	if err := r.loadTrust(cfg); err != nil {
		return nil, err
	}
	// Generation 0 is the signed config's generic workloads.
	r.current = cellspec.Spec{Schema: cellspec.Schema, Identity: r.identity, RequiresBinary: 1}
	for _, role := range slices.Sorted(maps.Keys(cfg.Controller.Workloads)) {
		profile := cfg.Controller.Workloads[role]
		if slices.Contains(r.reserved, role) || role == terrabase.Role {
			r.fixed[role] = profile
			continue
		}
		service := cellspec.Service{Role: role, Profile: profile}
		// Generation 0 reconciles exactly what the signed config already
		// reconciled.
		if autoscaleConfig != nil {
			for _, spec := range autoscaleConfig.Services {
				if spec.Role == role {
					service.Spec = &spec
				}
			}
		}
		r.current.Services = append(r.current.Services, service)
	}
	r.current.RequiresBinary = r.current.Level()
	return r, nil
}

// loadTrust takes the roots and deployment identity from the accepted image.
func (r *specRegistry) loadTrust(cfg Config) error {
	if cfg.Controller.SpecTrust != nil {
		return errors.New("production controller uses the image trust roots")
	}
	accepted, inputs, err := specAcceptedInputs()
	if err != nil {
		return fmt.Errorf("load accepted trust roots for cell specs: %w", err)
	}
	identity := cellspec.Identity{DeploymentID: accepted.DeploymentID,
		Cell: strings.ToLower(accepted.Cell), Environment: accepted.Environment}
	if identity.Cell != cfg.NATS.Cell {
		return errors.New("accepted trust cell differs from the controller cell")
	}
	if err := identity.Validate(); err != nil {
		return err
	}
	r.identity = identity
	return r.openRoots(inputs.Genesis, inputs.Chain, bootstrapstart.RootChainFile)
}

// openRoots builds the cell's root chain from genesis and the adopted chain.
func (r *specRegistry) openRoots(genesis trust.Keyring, chain trust.RootChain, path string) error {
	roots, err := newRootRegistry(genesis, trust.ChainIdentity{DeploymentID: r.identity.DeploymentID,
		Cell: r.identity.Cell, Environment: r.identity.Environment}, chain, path)
	if err != nil {
		return err
	}
	roots.keeps = r.keepsStoredSpec
	roots.fence = &r.launches
	r.roots = roots
	return nil

func newAcceptedSpecTrust(t *testing.T, cfg *Config) {
	t.Helper()
	accepted := bootstrapstart.AcceptedIdentity{DeploymentID: "01ARZ3NDEKTSV4RRFFQ69G5FAV",
		Cell: cfg.NATS.Cell, Environment: "test"}
	roots := testSpecRoots(t)
	if spec := cfg.Controller.SpecTrust; spec != nil {
		accepted.DeploymentID, accepted.Environment = spec.DeploymentID, spec.Environment
		wire, err := os.ReadFile(spec.RootPublicKeyFile)
		if err != nil {
			t.Fatal(err)
		}
		block, _ := pem.Decode(wire)
		if block == nil || block.Type != "PUBLIC KEY" {
			t.Fatal("spec trust root is not a PEM public key")
		}
		key, err := x509.ParsePKIXPublicKey(block.Bytes)
		if err != nil {
			t.Fatal(err)
		}
		public, ok := key.(ed25519.PublicKey)
		if !ok {
			t.Fatal("spec trust root is not Ed25519")
		}
		roots, err = trust.ParseKeyring(public)
		if err != nil {
			t.Fatal(err)
		}
	}
	cfg.Controller.SpecTrust = nil
	previous := specAcceptedInputs
	specAcceptedInputs = func() (bootstrapstart.AcceptedIdentity, bootstrapstart.TrustInputs, error) {
		chain := trust.RootChain{Version: 1}
		identity := trust.ChainIdentity{DeploymentID: accepted.DeploymentID, Cell: accepted.Cell, Environment: accepted.Environment}
		verified, err := trust.VerifyRootChain(roots, identity, chain)
		return accepted, bootstrapstart.TrustInputs{ChainIdentity: identity, Genesis: roots, Chain: chain, Roots: verified}, err
	}
	t.Cleanup(func() { specAcceptedInputs = previous })
}

func testSpecRoots(t *testing.T) trust.Keyring {
	t.Helper()
	public, _, err := ed25519.GenerateKey(rand.Reader)
	if err != nil {
		t.Fatal(err)
	}
	roots, err := trust.ParseKeyring(public)
	if err != nil {
		t.Fatal(err)
	}
	return roots
}

func newRootRegistry(genesis trust.Keyring, identity trust.ChainIdentity, chain trust.RootChain, path string) (*rootRegistry, error) {
	verified, err := trust.VerifyRootChain(genesis, identity, chain)
	if err != nil {
		return nil, fmt.Errorf("verify adopted root chain: %w", err)
	}
	return &rootRegistry{genesis: genesis, identity: identity, path: path, chain: chain, verified: verified,
		changed: make(chan struct{}, 1)}, nil
}

func (r *specRegistry) validate(spec cellspec.Spec) error {
	if len(spec.Signers) != 0 {
		if _, err := newSignerSet(spec.Signers); err != nil {
			return fmt.Errorf("cell spec signers: %w", err)
		}
	}
	profiles := maps.Clone(r.fixed)
	var specs []workload.ServiceSpec
	for _, service := range spec.Services {
		if slices.Contains(r.reserved, service.Role) {
			return fmt.Errorf("role %q is owned by placement and stays in the signed controller config", service.Role)
		}
		if service.Role == terrabase.Role && (!r.terraBaseCA || service.Spec != nil) {
			return fmt.Errorf("service %q needs the signed TerraBase member CA and is never reconciled", service.Role)
		}
		for _, actor := range service.Releasers {
			if !slices.ContainsFunc(r.effectiveSigners(spec), func(signer TrustedSignerConfig) bool { return signer.Actor == actor }) {
				return fmt.Errorf("service %q releaser %q is not a trusted signer", service.Role, actor)
			}
		}
		profiles[service.Role] = service.Profile
		if service.Spec != nil {
			specs = append(specs, *service.Spec)
		}
	}
	if err := validateWorkloadProfiles(r.cell, profiles); err != nil {
		return err
	}
	if err := r.validateHostGrants(spec.HostGrants, profiles); err != nil {
		return err
	}
	if desired := spec.OCIDesired; desired != nil {
		if r.ociRegion == nil {
			return errors.New("desired OCI resources need the signed region config")
		}
		if _, _, err := desiredSets(*desired, string(r.ociRegion.Region), *r.ociRegion); err != nil {
			return err
		}
	}
	if fence, public := spec.ReleaseFence, r.publicLB; fence != nil && public != nil && fence.LoadBalancerID == public.LoadBalancerID {
		for _, set := range fence.BackendSets {
			if set.Name == public.BackendSet {
				// The reconciler would return a fenced backend to rotation.
				return fmt.Errorf("release_fence names backend set %q, which oci_reconcile.public_lb owns", set.Name)
			}
		}
	}
	limit, headroom := r.artifactStoreLimit, specStoreHeadroomBytes
	if spec.MachinesAPI != nil {
		limit, headroom = limit-machinesAPIStoreBytes, headroom+machinesAPIStoreBytes
	}
	if store := spec.ArtifactStore; store != nil && store.MaxBytes > limit {
		return fmt.Errorf("artifact_store max_bytes %d exceeds this controller's %d: its embedded NATS store_max_bytes less %d bytes for control state",
			store.MaxBytes, max(limit, 0), headroom)
	}
	return validateAutoscaleConfig(&AutoscaleConfig{Services: specs}, profiles)
}

func (r *specRegistry) adopt(spec cellspec.Spec, revision uint64) {
	r.launches.Lock()
	defer r.launches.Unlock()
	r.mu.Lock()
	defer r.mu.Unlock()
	if revision <= r.revision {
		return
	}
	// A stored record only moves forward; an older signed spec written into
	// the record is a rollback, whatever its revision.
	if spec.Generation < r.current.Generation || spec.Generation == r.current.Generation && !sameSpec(spec, r.current) {
		slog.Error("stored cell spec would roll back the current spec; keeping it", observability.ComponentKey, "cellspec",
			"generation", spec.Generation, "current", r.current.Generation, "revision", revision)
		return
	}
	// The signers change first, and a spec whose signers are refused is not
	// adopted at all, so no consumer sees one generation's spec with
	// another's signers.
	if r.replaceSigners != nil {
		if err := r.replaceSigners(r.effectiveSigners(spec)); err != nil {
			slog.Error("stored cell spec signers refused; keeping the current spec", observability.ComponentKey, "cellspec",
				"generation", spec.Generation, "revision", revision, "error", err)
			return
		}
	}
	r.current, r.revision = spec, revision
	slog.Info("cell spec adopted", observability.ComponentKey, "cellspec", "generation", spec.Generation,
		"revision", revision, "roles", len(spec.Services))
	if r.changed != nil {
		profiles, specs := r.effectiveLocked()
		r.changed(profiles, specs)
	}
}

func (r *specRegistry) ociDesired() *cellspec.OCIDesired {
	r.mu.Lock()
	defer r.mu.Unlock()
	if r.current.OCIDesired != nil {
		return r.current.OCIDesired
	}
	return r.signedDesired
}

func (r *specRegistry) withSigned(spec cellspec.Spec) cellspec.Spec {
	if spec.OCIDesired == nil {
		spec.OCIDesired = r.signedDesired
	}
	spec.Signers = r.effectiveSigners(spec)
	if spec.ArtifactStore == nil {
		spec.ArtifactStore = &cellspec.ArtifactStore{MaxBytes: r.signedArtifactStore}
	}
	return spec
}

func AuthorityChanges(current, next Spec, signed map[string]Profile) []string {
	var changes []string
	for _, service := range next.Services {
		before, _ := current.Find(service.Role)
		for _, actor := range service.Releasers {
			if !slices.Contains(before.Releasers, actor) {
				changes = append(changes, fmt.Sprintf("service %s releaser %s", service.Role, actor))
			}
		}
		for key, ref := range service.Profile.Secrets {
			if before.Profile.Secrets[key] != ref {
				changes = append(changes, fmt.Sprintf("service %s Vault secrets", service.Role))
				break
			}
		}
	}
	for _, grant := range next.HostGrants {
		if before, ok := current.Grant(grant.Node); !ok || !reflect.DeepEqual(before, grant) {
			changes = append(changes, "host grant "+grant.Node)
		}
	}
	for _, image := range next.HostImages {
		if before, ok := current.HostImage(image.ImageID); !ok || !reflect.DeepEqual(before, image) {
			changes = append(changes, "host image "+image.ImageID)
		}
	}
	if next.LaunchImage != "" && next.LaunchImage != current.LaunchImage {
		changes = append(changes, "launch image "+next.LaunchImage)
	}
	// The publish key writes what every SDK trusts for region discovery.
	if next.Atlas != nil && !reflect.DeepEqual(current.Atlas, next.Atlas) {
		changes = append(changes, "atlas")
	}
	// A fence takes load balancer backends out of rotation with the
	// controllers' instance principal.
	if next.ReleaseFence != nil && !reflect.DeepEqual(current.ReleaseFence, next.ReleaseFence) {
		changes = append(changes, "release fence")
	}
	// The API's issuer, clients and members decide who reads the cell.
	if next.MachinesAPI != nil && !reflect.DeepEqual(current.MachinesAPI, next.MachinesAPI) {
		changes = append(changes, "machines api")
	}
	// The token decides who reads the cell's dashboard.
	if next.Dashboard != nil && !reflect.DeepEqual(current.Dashboard, next.Dashboard) {
		changes = append(changes, "dashboard")
	}
	// Enrollment widens the node's Vault and manager authority. Once it is
	// authorized, changing only verified client artifacts is an ordinary bump.
	if next.NetBird != nil && (current.NetBird == nil || !reflect.DeepEqual(current.NetBird.Enrollment, next.NetBird.Enrollment)) {
		changes = append(changes, "netbird enrollment")
	}
	changes = append(changes, ociDesiredChanges(current.OCIDesired, next.OCIDesired)...)
	for _, actor := range signerChanges(current.Signers, next.Signers) {
		changes = append(changes, "signer "+actor)
	}

func ociDesiredChanges(before, after *OCIDesired) []string {
	if before == nil {
		before = &OCIDesired{}
	}
	if after == nil {
		after = &OCIDesired{}
	}
	var changes []string
	if after.Prune && !before.Prune {
		changes = append(changes, "oci_desired prune")
	}
	if after.Prune && before.Prune && pruneDelay(after) < pruneDelay(before) {
		changes = append(changes, "oci_desired prune delay")
	}
	changes = append(changes, desiredChanges("nsg_rules", before.NSGRules, after.NSGRules, after.Prune)...)
	changes = append(changes, desiredChanges("security_lists", before.SecurityLists, after.SecurityLists, after.Prune)...)
	changes = append(changes, desiredChanges("route_tables", before.RouteTables, after.RouteTables, after.Prune)...)
	return append(changes, desiredChanges("buckets", before.Buckets, after.Buckets, after.Prune)...)
}

func pruneDelay(d *OCIDesired) int {
	if d.PruneDelaySeconds == 0 {
		return 60 * 60
	}
	return d.PruneDelaySeconds
}

func desiredChanges[S any](kind string, before, after map[string]OCIDesiredEntry[S], prune bool) []string {
	var changes []string
	for _, name := range slices.Sorted(maps.Keys(after)) {
		entry := after[name]
		if previous, ok := before[name]; !ok || !reflect.DeepEqual(previous, entry) {
			changes = append(changes, "oci_desired "+kind+" "+name)
		}
	}
	for _, name := range slices.Sorted(maps.Keys(before)) {
		if _, kept := after[name]; !kept && prune {
			changes = append(changes, "oci_desired "+kind+" "+name+" pruned")
		}
	}
	return changes
}

func (o Ownership) Validate() error {
	if !tokenPattern.MatchString(o.Owner) {
		return errors.New("OCI resource ownership requires a token owner")
	}
	if o.Mode != "" && o.Mode != TagModeFreeform || o.Namespace != "" {
		return errors.New("OCI ownership uses freeform tags; alternate tag configuration is retired")
	}
	return nil
}

func (runtime *runtimeObservability) startDecisionJournal(ctx context.Context) {
	journal := decisionlog.NewJournal(decisionlog.JournalConfig{Region: runtime.cell, Member: runtime.member,
		Log: true})
	ctx, cancel := context.WithCancel(ctx)
	runtime.journalCtx, runtime.stopJournal = ctx, cancel
	restore := decisionlog.SetDefault(journal)
	context.AfterFunc(ctx, restore)
	runtime.registry.Register(decisionlog.Metrics)
	runtime.journal = journal
	go func() { _ = journal.Run(ctx) }()
}

// attachJournal opens the replicated stream, serves cross-region queries,
// and starts history collection and query providers independently of
// whether the private listener runs. Nothing here can fail the
// controller: every step that cannot start is logged and skipped.
func (runtime *runtimeObservability) attachJournal(ctx context.Context, observed controllerObservation,
	collector *observability.Collector, cluster observability.ClusterSource,
) {
	journal := runtime.journal
	if journal == nil {
		return
	}
	// Everything feeding the journal ends with it.
	ctx, cancel := context.WithCancel(ctx)
	context.AfterFunc(runtime.journalCtx, cancel)
	conn := observed.nats.Conn()
	go openDecisionStream(ctx, observed.nats.JetStream(), runtime.cell, observed.replicas, journal)
	if _, err := decisionlog.ServeQueries(ctx, conn, runtime.cell, journal); err != nil {
		slog.WarnContext(ctx, "decision query responder unavailable", observability.ComponentKey, "decision", "error", err)
	}
	if observed.nats != nil {
		go watchControlPlane(ctx, runtime.cell, runtime.member, observed.authority, observed.nats, observed.replicas)
	}
	links, err := regionlink.New(runtime.cell, conn, nil, regionRequestTimeout)
	if err != nil {
		slog.WarnContext(ctx, "region links unavailable", observability.ComponentKey, "regionview", "error", err)
		return
	}
	// Roster peers are reachable through the cell connection: the contract
	// imports exactly their region summary and decision query services over
	// the leafnodes, so they are linked rather than shown as not_linked.
	linkRoster(links, conn, observed.peers)
	if cluster != nil {
		// The sampler, the insight engine and the region view share one
		// scatter-gather per few seconds instead of one each.
		cluster = &sharedCluster{source: cluster, cache: observability.Cache[observability.ClusterSnapshot]{TTL: 3 * time.Second}}
	}
	history := observability.NewHistory(observability.HistoryConfig{})
	runtime.registry.Register(observability.HistoryMetrics)
	sharedHistory := &hostMetricHistory{local: history,
		shared: observability.NewHistory(observability.HistoryConfig{Interval: observability.HostMetricInterval})}
	runtime.registry.RegisterWriter(sharedHistory.writeMetrics)
	go sharedHistory.run(ctx, observed.nats.JetStream(), runtime.cell, observed.replicas, observed.hostLoad, runtime.events)
	go runHistorySampler(ctx, observed, runtime.member, history,
		withoutHostMetricSamples(withAutoscaleSamples(observability.ClusterCollect(cluster, collector), observed.autoscalers, observed.hostLoad)))
	regions := &regionview.Provider{Cell: runtime.cell, Cluster: cluster, Snapshot: collector, History: sharedHistory,
		Decisions: journal, Links: links, Nodes: observed.nodes, LinkProbes: observed.linkProbes,
		NativeRegion: observed.nativeTerraBaseRegion, Cost: observed.cost}
	insightConfig := insights.Config{Region: runtime.cell, Cluster: cluster, Local: collector,
		History: sharedHistory, Decisions: journal, Reachability: regions, Holds: observed.holds}
	// Optional providers of the other slices: each stays nil, and its rules
	// silent, unless that slice runs on this controller.
	var volumes insights.VolumeProvider
	if observed.placements != nil {
		volumes = placementVolumes{store: observed.placements}
		insightConfig.Volumes = volumes
	}
	if observed.autoscalers != nil {
		insightConfig.Autoscalers = workloadAutoscalers{reconciler: observed.autoscalers}
	}
	var rolloutSource dashboard.RolloutSource
	if observed.rollouts != nil {
		rolloutSource = dashboardRollouts{store: observed.rollouts}
		insightConfig.Rollouts = observed.rollouts
	}
	if observed.budgets != nil {
		insightConfig.Budgets = observed.budgets
	}
	if observed.ociResources != nil {
		insightConfig.OCIResources = observed.ociResources
	}
	engine := insights.NewEngine(insightConfig)
	regions.Insights = engine
	go func() { _ = engine.Run(ctx) }()
	globalView := runtime.startGlobalView(ctx, observed, links, cluster, volumes)
	if _, err := regionview.Serve(ctx, conn, runtime.cell, regions); err != nil {
		slog.WarnContext(ctx, "region summary responder unavailable", observability.ComponentKey, "regionview", "error", err)
	}
	federation := decisionlog.Federation{Local: journal, Links: links}
	providers := journalProviders{Decisions: federation, Live: journal, History: sharedHistory, Insights: engine,
		Summarizer: insights.Summarizer{Decisions: federation, Insights: engine, Scope: "all regions",
			AttentionScope: strings.ToUpper(runtime.cell)},
		Global: globalView, Probes: regions, Foundation: observed.foundation}
	runtime.providers.Store(&providers)
	if runtime.server != nil {
		mountJournalAPI(runtime.server, providers)
	}
	// Rollout, version, qualification and inventory providers stay nil
	// until a controller runs their slices; the pages say so.
	runtime.attachBoards(func() {
		runtime.boardJournal = &dashboard.Journal{Decisions: providers.Decisions, Live: providers.Live,
			History: providers.History, Insights: providers.Insights, Summaries: providers.Summarizer,
			Local: regions.Local, Volumes: volumes, Rollouts: rolloutSource,
			Global: globalView, Capacity: observed.capacity, Inventory: observed.inventory}
	})
}

func openDecisionStream(ctx context.Context, js jetstream.JetStream, cell string, replicas int,
	journal *decisionlog.Journal,
) {
	for attempt := 1; ; attempt++ {
		openCtx, cancel := context.WithTimeout(ctx, 20*time.Second)
		stream, err := decisionlog.OpenStream(openCtx, js, decisionlog.StreamConfig{Cell: cell, Replicas: replicas})
		cancel()
		if err == nil {
			journal.Attach(stream, stream)
			_ = stream.Tail(ctx, journal, 0)
			return
		}
		if ctx.Err() != nil {
			return
		}
		if attempt == 1 || attempt%12 == 0 {
			slog.WarnContext(openCtx, "decision stream not open yet; decisions stay in memory", observability.ComponentKey,
				"decision", "attempt", attempt, "error", err)
		}
		select {
		case <-ctx.Done():
			return
		case <-time.After(journalOpenRetry):
		}
	}
}

func runHistorySampler(ctx context.Context, observed controllerObservation, member string,
	history *observability.History, collect func(context.Context) []observability.Sample,
) {
	sampler := observability.HistorySampler{Store: history, Collect: collect, Member: member}
	if conn := observed.nats.Conn(); conn != nil {
		limit := int32(min(conn.MaxPayload()-8<<10, 1<<20))
		openCtx, cancel := context.WithTimeout(ctx, 10*time.Second)
		snapshots, err := observability.OpenHistorySnapshots(openCtx, observed.nats.JetStream(), observed.replicas, limit)
		cancel()
		if err == nil {
			sampler.Snapshots, sampler.SnapshotLimit = snapshots, int(limit)
		} else {
			slog.InfoContext(openCtx, "metric history snapshots unavailable; history restarts empty", observability.ComponentKey,
				"observability", "error", err)
		}
	}
	_ = sampler.Run(ctx)
}

func watchControlPlane(ctx context.Context, cell, member string, fencer authority.Fencer, nats clusterHealth,
	replicas int,
) {
	if fencer == nil || nats == nil {
		return
	}
	healthEvery := clusterHealthInterval
	ticker := time.NewTicker(controlPlaneWatchInterval)
	defer ticker.Stop()
	var observedEpoch uint64
	wasLeader, wasMetaLeader := false, false
	metaLeader := ""
	healthy, everHealthy := false, false
	var lastHealthCheck time.Time
	for {
		ctx := observability.StartTrace(ctx)
		snapshot := fencer.Current()
		leading := snapshot.Leader && snapshot.Ready
		if leading && (!wasLeader || snapshot.Epoch != observedEpoch) {
			recordLeadership(ctx, cell, member, snapshot, observedEpoch)
		}
		wasLeader = leading
		if snapshot.Epoch > 0 {
			observedEpoch = snapshot.Epoch
		}
		if time.Since(lastHealthCheck) >= healthEvery {
			lastHealthCheck = time.Now()
			ready := nats.FullClusterReady(replicas)
			// The first full formation at startup is not a recovery. A
			// follower records it too when it observes no valid lease: the
			// authority runtime keeps its own candidate as OwnerID on
			// control-log failures, so an empty OwnerID is not the test.
			//
			// healthy is the state last journaled, not the last observed: a
			// follower that sees a transition while a lease looks valid
			// leaves it unreported, so if that leader died with the cluster
			// the next leader (or a member that sees the lease expire)
			// still journals it. A leadership change can therefore journal
			// one transition twice, never zero times.
			if ready != healthy && everHealthy && (leading || !validLease(snapshot, time.Now())) {
				recordClusterHealth(ctx, cell, member, nats, replicas, ready, snapshot.Epoch)
				healthy = ready
			}
			if !everHealthy || leading {
				healthy = ready
			}
			everHealthy = everHealthy || ready
			viewCtx, cancel := context.WithTimeout(ctx, 2*time.Second)
			if view, err := nats.Observe(viewCtx); err == nil {
				if view.IsMetaLeader && !wasMetaLeader {
					recordMetaLeadership(ctx, cell, member, view, metaLeader, snapshot.Epoch)
				}
				wasMetaLeader = view.IsMetaLeader
				if view.MetaLeader != "" {
					metaLeader = view.MetaLeader
				}
			}
			cancel()
		}
		select {
		case <-ctx.Done():
			return
		case <-ticker.C:
		}
	}

func recordLeadership(ctx context.Context, cell, member string, snapshot authority.Snapshot, previousEpoch uint64) {
	reason := "This controller acquired the regional authority lease."
	if previousEpoch > 0 && previousEpoch != snapshot.Epoch {
		reason = fmt.Sprintf("This controller acquired the regional authority lease, ending epoch %d.", previousEpoch)
	}
	decisionlog.Record(ctx, decisionlog.Decision{
		Region:  cell,
		Actor:   decisionlog.Actor{Slice: "authority"},
		Kind:    decisionlog.KindLeaderChanged,
		Subject: decisionlog.Subject{Kind: "member", ID: member},
		Summary: fmt.Sprintf("%s became the regional authority leader (epoch %d)", member, snapshot.Epoch),
		Reason:  reason,
		Rule:    "fenced JetStream authority lease",
		Status:  decisionlog.StatusSucceeded,
		Epoch:   snapshot.Epoch,
		Signals: []decisionlog.Signal{{Name: "epoch", Value: float64(snapshot.Epoch)},
			{Name: "lease_expires_at", Text: snapshot.ExpiresAt.UTC().Format(time.RFC3339)}},
	})
}

func (s Snapshot) CanMutate() bool {
	return entityid.Valid(s.DeploymentID) && s.Ready && s.Leader && s.Epoch > 0 && s.Revision > 0 &&
		!s.ExpiresAt.IsZero() && time.Now().Before(s.ExpiresAt)
}

// The owner is the newest valid lease any member observes, whatever
// the member order; the holder's own report wins a tie. A member
// that observes no ready lease (control-log failures keep its own
// candidate as OwnerID) is no evidence of a leader.
if authority := member.Authority; authority != nil && authority.Ready && authority.Epoch > 0 &&
	(authority.Leader || authority.OwnerID != "") {
	owner := authority.OwnerID
	if authority.Leader {
		owner = member.Member
	}
	if authority.Epoch > summary.Leaders.Epoch || authority.Epoch == summary.Leaders.Epoch && authority.Leader {
		summary.Leaders.Authority, summary.Leaders.Epoch = owner, authority.Epoch
	}
}

func ServeSnapshots(ctx context.Context, conn *nats.Conn, cell string, source SnapshotSource) (*nats.Subscription, error) {
	if conn == nil || source == nil {
		return nil, errors.New("snapshot responder requires a connection and a source")
	}
	subject, err := protocol.ObservabilitySubject(cell, SnapshotLeaf)
	if err != nil {
		return nil, err
	}
	subscription, err := conn.Subscribe(subject, func(message *nats.Msg) {
		if message.Reply == "" || len(message.Data) > maxSnapshotRequestBytes {
			return
		}
		var request snapshotRequest
		if err := json.Unmarshal(message.Data, &request); err != nil || request.Version != SnapshotVersion {
			return
		}
		answerCtx, cancel := context.WithTimeout(ctx, snapshotAnswerTimeout)
		defer cancel()
		snapshot, err := source.Snapshot(answerCtx, request.IncludeMetrics)
		if err != nil {
			return
		}
		data, err := json.Marshal(snapshot)
		if err == nil && int64(len(data)) > conn.MaxPayload() {
			// Drop the exposition rather than the whole answer.
			snapshot.Metrics, snapshot.MetricsTruncated = "", true
			data, err = json.Marshal(snapshot)
		}
		if err != nil || int64(len(data)) > conn.MaxPayload() {
			return
		}
		_ = message.Respond(data)
	})
	if err != nil {
		return nil, err
	}
	context.AfterFunc(ctx, func() { _ = subscription.Unsubscribe() })
	return subscription, nil
}

// Aggregator scatter-gathers MemberSnapshot values from every controller of
// one cell. It implements ClusterSource.
type Aggregator struct {
	conn     *nats.Conn
	cell     string
	subject  string
	expected []string
	timeout  time.Duration
}

// NewAggregator binds a cell and its expected member names. With expected
// members known, a gather ends as soon as all of them answer.
func NewAggregator(conn *nats.Conn, cell string, expected []string, timeout time.Duration) (*Aggregator, error) {
	if conn == nil {
		return nil, errors.New("snapshot aggregator requires a connection")
	}
	subject, err := protocol.ObservabilitySubject(cell, SnapshotLeaf)
	if err != nil {
		return nil, err
	}
	if len(expected) > maxClusterMembers {
		return nil, errors.New("snapshot aggregator expects too many members")
	}
	if timeout <= 0 {
		timeout = DefaultAggregationTimeout
	}
	expected = slices.Clone(expected)
	slices.Sort(expected)
	return &Aggregator{conn: conn, cell: cell, subject: subject, expected: slices.Compact(expected), timeout: timeout}, nil
}

// Cluster gathers one snapshot per answering member. A reply for another
// cell, an unknown member when the roster is known, or a duplicate member is
// ignored. Missing members are listed rather than failing the call.
func (aggregator *Aggregator) Cluster(ctx context.Context, includeMetrics bool) (ClusterSnapshot, error) {
	request, err := json.Marshal(snapshotRequest{Version: SnapshotVersion, IncludeMetrics: includeMetrics})
	if err != nil {
		return ClusterSnapshot{}, err
	}
	inbox := aggregator.conn.NewInbox()
	replies := make(chan *nats.Msg, maxClusterMembers*2)
	subscription, err := aggregator.conn.ChanSubscribe(inbox, replies)
	if err != nil {
		return ClusterSnapshot{}, err
	}
	defer subscription.Unsubscribe()
	if err := aggregator.conn.PublishRequest(aggregator.subject, inbox, request); err != nil {
		return ClusterSnapshot{}, err
	}
	timer := time.NewTimer(aggregator.timeout)
	defer timer.Stop()
	members := map[string]MemberSnapshot{}
	cluster := ClusterSnapshot{Cell: aggregator.cell, Expected: aggregator.expected}
gather:
	for len(aggregator.expected) == 0 || len(members) < len(aggregator.expected) {
		select {
		case <-ctx.Done():
			return ClusterSnapshot{}, ctx.Err()
		case <-timer.C:
			break gather
		case message := <-replies:
			var snapshot MemberSnapshot
			if err := json.Unmarshal(message.Data, &snapshot); err != nil || snapshot.Version < 1 ||
				snapshot.Cell != aggregator.cell || snapshot.Member == "" {
				continue
			}
			if len(aggregator.expected) > 0 {
				if _, known := slices.BinarySearch(aggregator.expected, snapshot.Member); !known {
					continue
				}
			}
			if _, duplicate := members[snapshot.Member]; duplicate || len(members) >= maxClusterMembers {
				continue
			}
			members[snapshot.Member] = snapshot
		}
	}
	for _, member := range slices.Sorted(maps.Keys(members)) {
		cluster.Members = append(cluster.Members, members[member])
	}
	for _, member := range aggregator.expected {
		if _, answered := members[member]; !answered {
			cluster.Missing = append(cluster.Missing, member)
		}
	}
	cluster.ObservedAt = time.Now().UTC()
	return cluster, nil
}

func OpenStore(ctx context.Context, js jetstream.JetStream, cell string, replicas int, fencer authority.Fencer) (*Store, error) {
	if js == nil || fencer == nil || !tokenRE.MatchString(cell) || replicas != 1 && replicas != 3 && replicas != 5 {
		return nil, fmt.Errorf("%w: rollout store configuration", ErrInvalid)
	}
	kv, err := js.CreateOrUpdateKeyValue(ctx, jetstream.KeyValueConfig{
		Bucket: Bucket, Storage: jetstream.FileStorage, Replicas: replicas, History: 8, MaxValueSize: maxRecordBytes,
	})
	if err != nil {
		return nil, fmt.Errorf("rollout store: %w", err)
	}
	return &Store{kv: kv, fencer: fencer, cell: cell}, nil
}

func (s *Store) Begin(ctx context.Context, spec Spec, now time.Time) (Record, uint64, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	if spec.Cell != s.cell {
		return Record{}, 0, fmt.Errorf("%w: rollout cell", ErrInvalid)
	}
	if err := s.fencer.Guard(ctx, spec.AuthorityEpoch); err != nil {
		return Record{}, 0, err
	}
	// An ID already bound to another rollout is refused before the cell
	// slot is reserved or the target's attempt is counted.
	bound := false
	if existing, _, err := s.Load(ctx, spec.RolloutID); err == nil {
		if err := sameRollout(existing, spec); err != nil {
			return Record{}, 0, err
		}
		bound = true
	} else if errors.Is(err, ErrAbandonedRollout) {
		if err := s.releaseSlot(ctx, spec.AuthorityEpoch, spec.RolloutID); err != nil {
			return Record{}, 0, err
		}
		return Record{}, 0, ErrAbandonedRollout
	} else if !errors.Is(err, jetstream.ErrKeyNotFound) {
		return Record{}, 0, err
	}
	if !bound {
		if release, kind, found, err := s.releaseStage(ctx, spec.RolloutID); err != nil {
			return Record{}, 0, err
		} else if found && (spec.ToDigest != release.Digest || spec.Kind != kind ||
			!spec.StartedAt.IsZero() && !spec.StartedAt.Equal(release.CreatedAt)) {
			return Record{}, 0, fmt.Errorf("%w: release stage binding", ErrConflict)
		} else if found {
			spec.StartedAt = release.CreatedAt
			bound = true
		}
	}

func (s *Store) createRecord(ctx context.Context, spec Spec, state CellState, now time.Time) (Record, uint64, error) {
	if existing, revision, err := s.Load(ctx, spec.RolloutID); err == nil {
		if err := sameRollout(existing, spec); err != nil {
			return Record{}, 0, err
		}
		return existing, revision, nil
	} else if !errors.Is(err, jetstream.ErrKeyNotFound) {
		return Record{}, 0, err
	}
	record, err := New(withKnownBad(spec, state.KnownBad), now)
	if err != nil {
		return Record{}, 0, err
	}
	encoded, err := protocol.EncodeJSON(record)
	if err != nil {
		return Record{}, 0, err
	}
	if err := s.fencer.Guard(ctx, record.AuthorityEpoch); err != nil {
		return Record{}, 0, err
	}
	revision, err := s.kv.Create(ctx, rolloutKey(record.RolloutID), encoded)
	if errors.Is(err, jetstream.ErrKeyExists) {
		return s.createRecord(ctx, spec, state, now)
	}
	if err != nil {
		return Record{}, 0, err
	}
	recordAdmitted(ctx, record)
	return record, revision, nil
}

// Commit replaces the record stored at revision with next. Identity fields,
// waves and policy are immutable, and the authority epoch may only change
// through Adopt. A terminal record releases the cell slot.
func (s *Store) Commit(ctx context.Context, revision uint64, next Record) (uint64, error) {
	if err := next.Validate(); err != nil {
		return 0, err
	}
	current, storedRevision, err := s.Load(ctx, next.RolloutID)
	if err != nil {
		return 0, err
	}
	if storedRevision != revision {
		return 0, ErrConflict
	}
	if current.AuthorityEpoch != next.AuthorityEpoch {
		return 0, ErrFenced
	}
	if current.Kind != next.Kind || current.Cell != next.Cell || current.FromDigest != next.FromDigest || current.ToDigest != next.ToDigest ||
		current.PolicyDigest != next.PolicyDigest || !slices.EqualFunc(current.Waves, next.Waves, slices.Equal) ||
		!current.StartedAt.Equal(next.StartedAt) {
		return 0, fmt.Errorf("%w: immutable rollout fields changed", ErrInvalid)
	}
	if current.Phase.Terminal() {
		return 0, ErrTerminal
	}
	encoded, err := protocol.EncodeJSON(next)
	if err != nil {
		return 0, err
	}
	if err := s.fencer.Guard(ctx, next.AuthorityEpoch); err != nil {
		return 0, err
	}
	newRevision, err := s.kv.Update(ctx, rolloutKey(next.RolloutID), encoded, revision)
	if errors.Is(err, jetstream.ErrKeyRevisionMismatch) || errors.Is(err, jetstream.ErrKeyExists) {
		return 0, ErrConflict
	}
	if err != nil {
		return 0, err
	}
	recordTransition(ctx, current, next)
	if err := s.syncCell(ctx, next); err != nil {
		return newRevision, fmt.Errorf("record committed; cell slot update pending: %w", err)
	}
	return newRevision, nil
}

func (s *Store) PublishRelease(ctx context.Context, epoch uint64, release Release) (Release, error) {
	if release.ReleaseSequence > 0 || len(release.SequenceMigration) > 0 || release.SequenceMigrationSHA256 != "" || release.RollbackOf != 0 {
		return Release{}, fmt.Errorf("%w: sequenced releases require signature admission; rollbacks require retained generation", ErrInvalid)
	}
	if err := rejectSequencedReceipt(release.Receipt); err != nil {
		return Release{}, err
	}
	return s.publishRelease(ctx, epoch, release, false)
}

func (s *Store) publishRelease(ctx context.Context, epoch uint64, release Release, rollback bool) (Release, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	if bad, err := s.IsKnownBad(ctx, release.Digest); err != nil {
		return Release{}, err
	} else if bad {
		return Release{}, ErrKnownBad
	}
	for range cellCASAttempts {
		desired, revision, err := s.Desired(ctx)
		if err != nil {
			return Release{}, err
		}
		seeded, err := s.seedReleaseOrdering(ctx, desired)
		if err != nil {
			return Release{}, err
		}
		next := seeded
		normalized := release
		normalized.Generation = desired.Generation() + 1
		normalized.ID = generationKey(s.cell, normalized.Generation)
		normalized.CreatedAt = release.CreatedAt.UTC()
		if err := normalized.validate(); err != nil {
			return Release{}, err
		}
		if !rollback {
			if err := advanceReleaseOrdering(&next, normalized, s.cell); err != nil {
				return Release{}, err
			}
		}
		if desired.Generation() > 0 && desired.Release.Digest == release.Digest {
			retry, err := s.retryUntouchedRelease(ctx, desired.Release, release)
			if err != nil {
				return Release{}, err
			}
			if !retry {
				if desired.SchemaVersion != DesiredSchemaVersion || desired.OrderingFloor.ReleaseSequence != next.OrderingFloor.ReleaseSequence || desired.LegacyFloor.Generation != next.LegacyFloor.Generation || desired.LegacyIssuanceFloor.Generation != next.LegacyIssuanceFloor.Generation {
					if err := s.writeDesired(ctx, epoch, next, revision); errors.Is(err, ErrConflict) {
						continue
					} else if err != nil {
						return Release{}, err
					}
				}
				return desired.Release, ErrReleaseUnchanged
			}
		}
		next.Release = normalized
		next.SchemaVersion = DesiredSchemaVersion
		if err := next.validate(s.cell); err != nil {
			return Release{}, err
		}
		// The generation being replaced is retained before the record
		// moves; a copy lost to a crash is written again by the next
		// publish, since the record still holds it.
		if desired.Generation() > 0 {
			if err := s.retain(ctx, epoch, desired.Release); err != nil {
				return Release{}, err
			}
		}
		if err := s.writeDesired(ctx, epoch, next, revision); errors.Is(err, ErrConflict) {
			continue
		} else if err != nil {
			return Release{}, err
		}
		if newest := next.Generation(); newest > ReleaseHistory {
			// Best effort: a missed purge only keeps one more old copy.
			oldest := newest - ReleaseHistory
			state, _, err := s.Cell(ctx)
			if err == nil && state.ActiveRolloutID != entityid.Derive(ControllerReleaseDomain, ReleaseRolloutID(oldest)) &&
				state.ActiveRolloutID != entityid.Derive(HostReleaseDomain, ReleaseRolloutID(oldest)) && s.fencer.Guard(ctx, epoch) == nil {
				_ = s.kv.Purge(ctx, generationKey(s.cell, oldest))
			}
		}
		return next.Release, nil
	}
	return Release{}, ErrConflict
}

func recordAdmitted(ctx context.Context, record Record) {
	id := decisionlog.Record(ctx, decisionlog.Decision{
		Region:  record.Cell,
		Actor:   decisionlog.Actor{Slice: "rollout"},
		Kind:    decisionlog.KindReleaseAdmitted,
		Subject: decisionlog.Subject{Kind: "release", ID: record.ToDigest, Name: string(record.Kind) + "/" + record.RolloutID},
		Summary: fmt.Sprintf("Admitted %s rollout %s of %d units in %d waves", record.Kind, record.RolloutID,
			len(record.Units), len(record.Waves)),
		Reason: "The target digest is not known bad and has attempts left.",
		Rule:   "rollout.begin",
		Status: decisionlog.StatusPending,
		Epoch:  record.AuthorityEpoch,
		Attrs: map[string]string{"rollout": record.RolloutID, "from": record.FromDigest,
			"policy": record.PolicyDigest},
	})
	decisionlog.Correlate(ReleaseCorrelation(record.ToDigest), id)
}

// recordTransition journals a committed phase change. Commit calls it after
// the CAS succeeded, so every transition is recorded exactly once.
func recordTransition(ctx context.Context, previous, next Record) {
	if previous.Phase == next.Phase && previous.WaveIndex == next.WaveIndex {
		return
	}
	kind, status, summary := transitionDecision(previous, next)
	if kind == "" {
		return
	}
	decisionlog.Record(ctx, decisionlog.Decision{
		Region:   next.Cell,
		Actor:    decisionlog.Actor{Slice: "rollout"},
		Kind:     kind,
		Subject:  decisionlog.Subject{Kind: "release", ID: next.ToDigest, Name: string(next.Kind) + "/" + next.RolloutID},
		Summary:  summary,
		Reason:   next.Reason,
		Rule:     "rollout." + string(next.Phase),
		Status:   status,
		Epoch:    next.AuthorityEpoch,
		ParentID: decisionlog.Correlated(ReleaseCorrelation(next.ToDigest)),
		Signals: []decisionlog.Signal{{Name: "wave", Value: float64(next.WaveIndex + 1),
			Comparison: "<=", Threshold: decisionlog.Threshold(float64(len(next.Waves)))}},
		Attrs: map[string]string{"rollout": next.RolloutID, "from_phase": string(previous.Phase),
			"phase": string(next.Phase), "wave": strconv.Itoa(next.WaveIndex)},
	})
}

func (s *Store) Rollouts(ctx context.Context) ([]insights.Rollout, error) {
	record, _, active, err := s.Active(ctx)
	if err != nil || !active {
		return nil, err
	}
	return []insights.Rollout{InsightRollout(record)}, nil
}

// InsightRollout is the insight view of one rollout record.
func InsightRollout(record Record) insights.Rollout {
	return insights.Rollout{ID: record.RolloutID, Release: record.ToDigest, Phase: string(record.Phase),
		PhaseStarted: record.PhaseStartedAt, PhaseDeadline: record.PhaseDeadline, Done: record.Phase.Terminal()}
}

func (s *Store) RecentRollouts(ctx context.Context) ([]insights.Rollout, error) {
	ctx, cancel := context.WithTimeout(ctx, 5*time.Second)
	defer cancel()
	if err := ctx.Err(); err != nil {
		return nil, err
	}
	desired, _, err := s.Desired(ctx)
	if err != nil {
		return nil, err
	}
	active, _, ok, err := s.Active(ctx)
	if err != nil {
		return nil, err
	}
	var records []insights.Rollout
	seen := make(map[string]bool)
	if ok {
		records = append(records, InsightRollout(active))
		seen[active.RolloutID] = true
	}
	newest := desired.Generation()
	for offset := range min(newest, uint64(ReleaseHistory)) {
		for _, domain := range []string{ControllerReleaseDomain, HostReleaseDomain} {
			if err := ctx.Err(); err != nil {
				return nil, err
			}
			id := entityid.Derive(domain, ReleaseRolloutID(newest-offset))
			if seen[id] {
				continue
			}
			record, _, err := s.Load(ctx, id)
			if errors.Is(err, jetstream.ErrKeyNotFound) || errors.Is(err, ErrAbandonedRollout) {
				continue
			}
			if err != nil {
				return nil, err
			}
			records = append(records, InsightRollout(record))
			seen[id] = true
		}
	}
	if err := ctx.Err(); err != nil {
		return nil, err
	}
	slices.SortFunc(records, func(a, b insights.Rollout) int {
		return cmp.Or(b.PhaseStarted.Compare(a.PhaseStarted), cmp.Compare(a.ID, b.ID))
	})
	return records, nil
}

func (source dashboardRollouts) Rollouts(ctx context.Context) ([]insights.Rollout, error) {
	return source.store.RecentRollouts(ctx)
}

func (source dashboardRollouts) Rollout(ctx context.Context, id string) (insights.Rollout, error) {
	ctx, cancel := context.WithTimeout(ctx, 5*time.Second)
	defer cancel()
	if err := ctx.Err(); err != nil {
		return insights.Rollout{}, err
	}
	// Load validates the ID before reading and verifies the record's key and cell.
	record, _, err := source.store.Load(ctx, id)
	if errors.Is(err, jetstream.ErrKeyNotFound) || errors.Is(err, rollout.ErrAbandonedRollout) {
		return insights.Rollout{}, dashboard.ErrRolloutNotFound
	}
	if err != nil {
		return insights.Rollout{}, err
	}
	return rollout.InsightRollout(record), nil
}

func (engine *Engine) Run(ctx context.Context) error {
	ticker := time.NewTicker(engine.config.Interval)
	defer ticker.Stop()
	for {
		engine.Evaluate(ctx)
		select {
		case <-ctx.Done():
			return ctx.Err()
		case <-ticker.C:
		}
	}
}

// gather reads every provider with a bounded deadline.
func (engine *Engine) gather(ctx context.Context, now time.Time) (*Inputs, []string) {
	config := engine.config
	ctx, cancel := context.WithTimeout(ctx, 5*time.Second)
	defer cancel()
	inputs := &Inputs{Now: now, Region: config.Region, Thresholds: config.Thresholds, History: config.History}
	var unavailable []string
	fail := func(name string) { unavailable = append(unavailable, name) }
	if config.Cluster != nil {
		if cluster, err := config.Cluster.Cluster(ctx, false); err == nil {
			inputs.Cluster = &cluster
		} else {
			fail("cluster")
		}
	}
	if inputs.Cluster == nil && config.Local != nil {
		if snapshot, err := config.Local.Snapshot(ctx, false); err == nil {
			inputs.Cluster = &observability.ClusterSnapshot{Cell: snapshot.Cell, ObservedAt: snapshot.ObservedAt,
				Members: []observability.MemberSnapshot{snapshot}}
		} else {
			fail("snapshot")
		}
	}
	if config.Decisions != nil {
		// Only the repeated-hold rule reads decisions: ask for exactly the
		// holds in its window, and treat an incomplete answer as no input
		// rather than as fewer holds.
		result, err := config.Decisions.Query(ctx, decisionlog.Query{Regions: []string{config.Region},
			Kinds: []decisionlog.Kind{decisionlog.KindHeld}, Since: now.Add(-decisionWindow), Limit: maxDecisions})
		switch {
		case err != nil || result.Truncated || result.Partial:
			fail("decisions")
		default:
			inputs.Decisions = result.Decisions
		}
	}
	check := func(name string, err error) {
		if err != nil {
			fail(name)
		}
	}
	var err error
	if config.Rollouts != nil {
		inputs.Rollouts, err = config.Rollouts.Rollouts(ctx)
		check("rollouts", err)
	}

func rolloutDeadline(inputs *Inputs) []Insight {
	var out []Insight
	for _, rollout := range inputs.Rollouts {
		if rollout.Done || rollout.PhaseDeadline.IsZero() || inputs.Now.Before(rollout.PhaseDeadline) {
			continue
		}
		over := inputs.Now.Sub(rollout.PhaseDeadline)
		severity := SeverityWarning
		if over > time.Hour {
			severity = SeverityCritical
		}
		out = append(out, Insight{Severity: severity, Score: over.Seconds(),
			Title: fmt.Sprintf("Rollout %s is past its %s deadline", shortID(rollout.ID), rollout.Phase),
			Why: fmt.Sprintf("Release %s has been in %s since %s, %s past its deadline.", shortID(rollout.Release),
				rollout.Phase, rollout.PhaseStarted.Format(time.RFC3339), roundDuration(over)),
			Entity: Entity{Kind: "rollout", ID: rollout.ID, Href: rolloutHref(rollout.ID)},
			Evidence: []Evidence{{Label: "Past deadline by", Value: over.Seconds(), Unit: "s", Comparison: "<=",
				Threshold: threshold(0)}},
			Actions: []Action{{Label: "Open rollouts", Href: "/rollouts"}}})
	}
	return out
}

func shortID(id string) string {
	id = strings.TrimPrefix(id, "sha256:")
	if len(id) > 12 {
		return id[:12]
	}
	return id
}

func (dashboard *Dashboard) loadJournal(ctx context.Context, current *view) {
	holder := dashboard.journal.Load()
	if holder == nil {
		return
	}
	journal := *holder
	current.Journal = &journal
	needs := current.Page.needs
	if journal.Global != nil {
		current.Global = journal.Global.Regions()
	}
	if needs&needLocal != 0 && journal.Local != nil {
		summary := journal.Local(ctx)
		current.LocalSummary = &summary
	}
	if journal.Insights != nil {
		evaluation := journal.Insights.Current()
		current.Evaluation = &evaluation
	}
	if needs&needSummaries != 0 && journal.Summaries != nil {
		for _, window := range summaryWindows {
			summary, err := dashboard.summaries.get(ctx, window.String(), func(ctx context.Context) (insights.Summary, error) {
				return journal.Summaries.Summary(ctx, window)
			})
			if err != nil {
				current.Unavailable = append(current.Unavailable, "summary "+window.String())
				continue
			}
			current.Summaries = append(current.Summaries, summary)
		}
	}
	if current.Page.decisions != nil && journal.Decisions != nil {
		if query := current.Page.decisions(*current); query != nil {
			key, _ := json.Marshal(query)
			result, err := dashboard.decisions.get(ctx, string(key), func(ctx context.Context) (decisionlog.Result, error) {
				return journal.Decisions.Query(ctx, *query)
			})
			if err != nil {
				current.Unavailable = append(current.Unavailable, "decision journal")
			} else {
				current.Decisions = &result
			}
		}
	}
	id := current.State.param("id")
	if id == "" && current.Page.chain != nil {
		id = current.Page.chain(*current)
	}
	if needs&needChain != 0 && id != "" && journal.Decisions != nil {
		// Cached like the decision queries: a chain lookup may fan out to
		// every linked region, and every open stream re-renders each tick.
		chain, err := dashboard.chains.get(ctx, id, func(ctx context.Context) (decisionlog.Chain, error) {
			return journal.Decisions.Chain(ctx, id)
		})
		switch {
		case err == nil:
			current.Chain = &chain
		case !errors.Is(err, decisionlog.ErrNotFound):
			current.Unavailable = append(current.Unavailable, "decision chain")
		}
	}
	if needs&needVersions != 0 {
		current.loadVersions(ctx)
	}
	if needs&needCapacity != 0 && journal.Capacity != nil {
		current.loadCapacity(ctx, journal.Capacity)
	}
	if needs&needRollouts != 0 && journal.Rollouts != nil {
		if rollouts, err := dashboard.rollouts.get(ctx, "recent", journal.Rollouts.Rollouts); err != nil {
			current.Unavailable = append(current.Unavailable, "rollouts")
		} else {
			current.Rollouts = rollouts
		}
	}
	if needs&needRollout != 0 && journal.Rollouts != nil {
		rollout, err := dashboard.rollout.get(ctx, current.Path["id"], func(ctx context.Context) (insights.Rollout, error) {
			return journal.Rollouts.Rollout(ctx, current.Path["id"])
		})
		switch {
		case err == nil:
			current.Rollout = &rollout
		case !errors.Is(err, ErrRolloutNotFound):
			current.Unavailable = append(current.Unavailable, "rollouts")
		}
	}

func (journal *Journal) Attach(sink Sink, archive Archive) {
	if sink == nil && archive == nil {
		return
	}
	journal.storage.Store(&storageHolder{sink: sink, archive: archive})
}

func (journal *Journal) currentStorage() (Sink, Archive) {
	if holder := journal.storage.Load(); holder != nil {
		return holder.sink, holder.archive
	}
	return nil, nil
}

// Record indexes the decision, queues it for publishing and returns its ID.
// A full queue drops the durable copy and counts it; the in-memory copy and
// the log line are kept.
func (journal *Journal) Record(ctx context.Context, decision Decision) string {
	if decision.Region == "" {
		decision.Region = journal.config.Region
	}
	if decision.Actor.Member == "" {
		decision.Actor.Member = journal.config.Member
	}
	decision = decision.Normalize(journal.config.Now())
	// A decision with a caller-chosen ID that is already indexed (an
	// idempotent replay) is indexed and logged once. Its durable copy is
	// queued again unless it is known to be stored, since the first attempt
	// may have been dropped from a full queue or failed to publish; the
	// stream deduplicates a copy that did land by its message ID.
	if fresh, durable := journal.ingest(decision, false); !fresh {
		if !durable {
			journal.enqueue(decision)
		}
		return decision.ID
	}
	journal.recorded.Add(1)
	recordedTotal.Inc()
	if journal.config.Log {
		LogRecorder{}.Record(ctx, decision)
	}
	journal.enqueue(decision)
	return decision.ID
}

func (journal *Journal) Query(ctx context.Context, query Query) (Result, error) {
	query = query.Normalized()
	// The replay flag is read before the snapshot: a replay that ends in
	// between leaves the result conservatively partial, never the reverse.
	replaying := journal.replaying.Load()
	decisions, coveredFrom := journal.snapshot()
	result := Result{}
	seen := make(map[string]struct{}, len(decisions))
	// fresh counts matches newer than coveredFrom. Memory evicts by arrival,
	// not by time, so only those are known to outrank everything evicted.
	fresh := 0
	for _, decision := range decisions {
		if query.Matches(decision) {
			result.Decisions = append(result.Decisions, decision)
			seen[decision.ID] = struct{}{}
			if decision.Time.After(coveredFrom) {
				fresh++
			}
		}
	}
	// While the stream tail is still replaying, memory does not hold the
	// region's history yet.
	if replaying {
		result.Partial = true
	}
	// Older decisions only matter when memory did not fill the page with
	// decisions newer than anything it evicted.
	older := !coveredFrom.IsZero() && (query.Since.IsZero() || query.Since.Before(coveredFrom))
	exhausted := !older
	if older && fresh < query.Limit {
		_, archive := journal.currentStorage()
		if archive == nil {
			result.Partial = true
		} else if complete, reachedFloor := journal.scanArchive(ctx, archive, query, coveredFrom, seen, &result); !complete {
			result.Partial = true
		} else {
			exhausted = reachedFloor
		}
	}
	SortNewestFirst(result.Decisions)
	switch {
	case len(result.Decisions) > query.Limit:
		result.Decisions = result.Decisions[:query.Limit]
		result.Truncated = true
	case len(result.Decisions) == query.Limit && !exhausted:
		// A full page with older history left unsearched may not be all:
		// say so rather than look exhaustive.
		result.Truncated = true
	}
	return result, nil
}

func (stream *Stream) Publish(ctx context.Context, decision Decision) error {
	data, err := json.Marshal(decision)
	if err != nil {
		return err
	}
	if len(data) > MaxRecordBytes {
		return errors.New("decision record exceeds its size bound")
	}
	_, err = stream.js.Publish(ctx, stream.subject, data, jetstream.WithMsgID(decision.ID))
	return err
}
